-- v780: update ONLY text/title of already-emitted, already-role-gated trames.
-- No new event, variant, visibility, vote or permission is added.
WITH edits (scenario_id,old_title,old_text,new_title,new_text) AS (
 VALUES
('001', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle l’ami à qui il réclame une dette. Cet ami semble quitter l’étage à 02 h 32. À 02 h 48, un autre visiteur entre dans l’hôtel. La chambre 222 n’est pas filmée.', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle un ami qui lui doit de l’argent. Cet ami semble partir à 02 h 32. Un autre homme arrive à 02 h 48.'),
('001', 'DETTE ET ENREGISTREMENT', 'Des messages confirment la dette de l’ancien ami. Après 02 h 55, un enregistrement capte un ordre d’effacement et une lutte. Les voix restent difficiles à identifier.', 'DETTE ET ENREGISTREMENT', 'Des messages confirment la dette de l’ami. Après 02 h 55, un enregistrement capte un ordre d’effacement et une lutte. Les voix restent incertaines.'),
('001', 'DEUX ALTERCATIONS, UNE LAME', 'Deux altercations ont eu lieu, avant 02 h 32 puis après 02 h 55. Un Opinel ensanglanté et essuyé est retrouvé dans une benne. Son porteur reste inconnu.', 'DEUX ALTERCATIONS, UNE LAME', 'Deux altercations ont eu lieu. Un couteau ensanglanté est retrouvé dans une benne, mais on ignore qui l’a utilisé.'),
('002', 'APPELS IGNORÉS', 'Plusieurs appels de Léon sont restés sans réponse le soir de sa mort, notamment ceux adressés au proche avec lequel sa relation était devenue conflictuelle.', 'APPELS IGNORÉS', 'Léon a appelé plusieurs fois un proche avec qui il se disputait. Ces appels sont restés sans réponse.'),
('002', 'DÉTRESSE ANCIENNE', 'Le dossier médical confirme que Léon allait mal avant les derniers événements. Son état s’est aggravé récemment.', 'DÉTRESSE ANCIENNE', 'Léon souffrait déjà avant les derniers conflits. Son état s’était récemment aggravé.'),
('002', 'DERNIER REFUGE', 'Léon cherchait encore du soutien auprès de ce même proche, malgré leur relation devenue difficile.', 'DERNIER REFUGE', 'Malgré leurs disputes, Léon comptait encore sur ce proche pour le comprendre.'),
('002', 'CRISES AVANT LES FAITS', 'Les prescriptions et recherches montrent des épisodes de détresse antérieurs aux conflits récents.', 'CRISES AVANT LES FAITS', 'Les dossiers montrent que Léon traversait déjà des crises avant les derniers conflits.'),
('002', 'DERNIER MESSAGE CALME', 'Quelques heures avant sa mort, Léon envoie un message très calme. Ce message ne permet pas de savoir ce qu’il va faire.', 'DERNIER MESSAGE CALME', 'Léon a envoyé un message calme peu avant sa mort. Il ne révèle pas ce qu’il allait faire.'),
('002', 'DERNIÈRE NUIT', 'Les journaux montrent plusieurs épisodes distincts avant la mort : humiliations, messages violents, appels sans réponse et départs.', 'DERNIÈRE NUIT', 'Avant sa mort, Léon a subi des humiliations, reçu des messages violents et passé des appels sans réponse.'),
('003', 'MESSAGE EFFACÉ', 'Un message supprimé évoque la nécessité de provoquer « un électrochoc » autour du programme.', 'MESSAGE EFFACÉ', 'Un message effacé parle de provoquer « un électrochoc » pour changer le programme Helios.'),
('003', 'ALERTE IGNORÉE', 'Une alerte de chaîne du froid est fermée sans contre-expertise.', 'ALERTE IGNORÉE', 'Une alerte sur la chaîne du froid a été classée sans nouvelle vérification.'),
('003', 'DOSSIER DISSIMULÉ', 'Une série d''incidents antérieurs a été retirée du dossier remis à l''autorité sanitaire.', 'DOSSIER DISSIMULÉ', 'Des incidents anciens ont été retirés du dossier remis aux autorités sanitaires.'),
('003', 'TENTATIVE D''ANNULATION', 'Un appel et un message montrent qu''une personne tente d''arrêter quelque chose quelques heures avant l''attaque.', 'TENTATIVE D''ANNULATION', 'Un appel et un message montrent que quelqu’un a tenté d’arrêter une action juste avant l’attaque.'),
('003', 'APPEL NON ABOUTI', 'Un appel urgent reste sans réponse pendant la fenêtre critique.', 'APPEL NON ABOUTI', 'Un appel urgent n’a reçu aucune réponse au moment critique.'),
('003', 'INSPECTION NEUTRALISÉE', 'Un contrôle externe est repoussé sur intervention administrative.', 'INSPECTION NEUTRALISÉE', 'Une inspection du Centre Helios a été repoussée après une intervention administrative.'),
('003', 'PANIQUE INTERNE', 'Après l’attaque, plusieurs employés cherchent d’abord qui a parlé avant de sécuriser les dossiers techniques.', 'PANIQUE INTERNE', 'Après l’attaque, des employés cherchent d’abord l’auteur de la fuite plutôt que de protéger les dossiers.'),
('003', 'TROIS FAILLES AVANT L’ATTAQUE', 'Avant l’attaque, trois faits sont déjà établis : un accès irrégulier, un transport hors procédure et des incidents cachés.', 'TROIS FAILLES AVANT L’ATTAQUE', 'Avant l’attaque, des documents signalent un accès irrégulier, un transport non autorisé et des incidents cachés.'),
('004', 'APPELS MANQUÉS', 'Les relevés montrent plusieurs appels successifs et des délais différents avant réponse.', 'APPELS MANQUÉS', 'Les proches de Sofia ont reçu plusieurs appels. Certains ont répondu plus tard que d’autres.'),
('004', 'APPEL COUPÉ', 'Un appel de moins de vingt secondes a lieu pendant une fenêtre où Sofia est encore consciente.', 'APPEL COUPÉ', 'Un appel de moins de vingt secondes a eu lieu alors que Sofia était encore consciente.'),
('004', 'SECOURS ENCORE POSSIBLES', 'L’intoxication est progressive. Plus tôt dans la nuit, une intervention médicale aurait encore pu changer l’issue.', 'SECOURS ENCORE POSSIBLES', 'L’intoxication de Sofia a été progressive. Appeler les secours plus tôt aurait pu lui sauver la vie.'),
('004', 'AUCUN TIERS DANS L''APPARTEMENT', 'Aucune trace ne montre qu''un tiers ait administré les substances.', 'AUCUN TIERS DANS L''APPARTEMENT', 'Aucune trace ne montre qu’une autre personne a donné les substances à Sofia.'),
('004', 'TROIS OCCASIONS D’APPELER', 'Les appels et les horaires montrent plusieurs moments où les secours pouvaient encore être contactés.', 'TROIS OCCASIONS D’APPELER', 'Plusieurs appels aux secours restaient possibles avant que l’état de Sofia ne devienne irréversible.'),
('004', 'PERSONNE N’APPELLE', 'Les trois personnes reçoivent un signal d’alerte à des moments différents. Aucune n’appelle immédiatement les secours.', 'PERSONNE N’APPELLE', 'Les trois proches ont reçu des alertes à des moments différents. Aucun n’a appelé immédiatement les secours.'),
('005', 'RITUEL IMPARFAIT', 'Le masque est le bon. La mise en scène, non. Plusieurs détails ne correspondent pas aux anciens meurtres.', 'RITUEL IMPARFAIT', 'Le masque correspond aux anciens crimes, mais plusieurs détails de la scène sont différents.'),
('005', 'DÉTAILS NON PUBLICS', 'Deux suspects connaissent des détails du Masque Blanc qui n’ont jamais été rendus publics.', 'DÉTAILS NON PUBLICS', 'Deux suspects connaissent des détails des anciens crimes du Masque Blanc restés secrets.'),
('005', 'VIOLENCE DIFFÉRENTE', 'Les blessures de Keller ne reproduisent pas la méthode des anciens meurtres. La violence est plus brutale et moins contrôlée.', 'VIOLENCE DIFFÉRENTE', 'Les blessures de Keller sont plus brutales que lors des anciens meurtres.'),
('005', 'MOTIF PERSONNEL', 'Des documents confirment qu’une femme proche d’un suspect a été gravement marquée par l’univers professionnel de Keller.', 'MOTIF PERSONNEL', 'Des documents montrent qu’une femme proche d’un suspect a beaucoup souffert à cause du travail de Keller.'),
('005', 'LIEN AVEC UNE ANCIENNE VICTIME', 'Un suspect a un lien direct avec une ancienne victime et connaît des éléments restés confidentiels.', 'LIEN AVEC UNE ANCIENNE VICTIME', 'Un suspect est lié à une ancienne victime et connaît des détails jamais rendus publics.'),
('005', 'MASQUE POSÉ APRÈS LA MORT', 'Le masque est placé sur Keller après sa mort. Il ne fait pas partie de l’agression initiale.', 'MASQUE POSÉ APRÈS LA MORT', 'Le masque a été placé sur Keller après sa mort.'),
('005', 'CRIME PERSONNEL', 'La confrontation avec Keller part d’un grief personnel. Le rituel apparaît seulement après le meurtre.', 'CRIME PERSONNEL', 'Le conflit avec Keller était personnel. Le masque n’a été ajouté qu’après sa mort.'),
('005', 'COPIE DU MASQUE BLANC', 'Les écarts avec les anciens crimes sont trop nombreux pour une reproduction exacte. La scène ressemble à une imitation.', 'COPIE DU MASQUE BLANC', 'La scène de Keller présente trop de différences avec les anciens crimes pour être une copie exacte.'),
('006', 'COUP AVANT LA CHUTE', 'Noé reçoit un coup avant sa chute. Le coup et la chute sont deux faits distincts.', 'COUP AVANT LA CHUTE', 'Noé a reçu un coup avant de tomber. Ce sont deux événements distincts.'),
('006', 'CINQ ANS DE SILENCE', 'Pendant cinq ans, les trois amis gardent la même version malgré la rupture progressive de leur groupe.', 'CINQ ANS DE SILENCE', 'Les trois amis ont répété la même version pendant cinq ans, même après leur brouille.'),
('006', 'MORT NON CERTAINE', 'Les constatations ne prouvent pas que les trois savaient avec certitude que Noé était mort juste après la chute.', 'MORT NON CERTAINE', 'Rien ne prouve que les trois amis savaient avec certitude que Noé était mort juste après sa chute.'),
('006', 'CORPS DÉPLACÉ', 'Après la chute, le corps de Noé est déplacé. Cette dissimulation a lieu après le coup initial.', 'CORPS DÉPLACÉ', 'Le corps de Noé a été déplacé après sa chute pour cacher ce qui s’était passé.'),
('006', 'DEUX ACTES DISTINCTS', 'Les traces séparent clairement le coup porté avant la chute des actes commis ensuite pour cacher les faits.', 'DEUX ACTES DISTINCTS', 'Un coup a été porté avant la chute. D’autres actes ont ensuite servi à cacher les faits.'),
('006', 'UN SEUL COUP INITIAL', 'Le coup initial est rattaché à une seule personne. Les autres actes viennent après.', 'UN SEUL COUP INITIAL', 'Une seule personne est liée au premier coup. Les autres actes sont survenus après.'),
('006', 'PACTE DE SILENCE', 'Les trois participent au silence. Tous ne participent pas de la même manière à la mort de Noé.', 'PACTE DE SILENCE', 'Tous les trois ont gardé le silence, mais leurs rôles dans la mort de Noé ne sont pas les mêmes.'),
('006', 'EXPERTISE TARDIVE', 'Cinq ans plus tard, l’expertise ne permet toujours pas d’affirmer qu’ils savaient que Noé était déjà mort au moment de cacher le corps.', 'EXPERTISE TARDIVE', 'Cinq ans après, on ignore encore si les trois amis savaient que Noé était mort quand ils ont caché son corps.'),
('007', 'BROUILLON ANTÉRIEUR', 'Le brouillon du testament existe avant la dispute familiale. La modification n’a pas été inventée après la mort.', 'BROUILLON ANTÉRIEUR', 'Un brouillon du testament existait déjà avant la dispute et le décès.'),
('007', 'ARGENT AVANT LA MORT', 'Un mouvement d’argent important a lieu avant le décès. Plusieurs membres de la famille avaient un intérêt financier réel.', 'ARGENT AVANT LA MORT', 'Un gros mouvement d’argent a eu lieu avant la mort. Plusieurs proches avaient un intérêt financier.'),
('007', 'DISPUTE PLUS TÔT', 'Un témoin place la dispute familiale plus tôt que l’heure donnée dans les premières déclarations.', 'DISPUTE PLUS TÔT', 'Un témoin situe la dispute familiale plus tôt que les premières déclarations.'),
('007', 'SIGNATURE AUTHENTIQUE', 'La signature du testament est authentique. Le problème est la pression exercée au moment de la signature.', 'SIGNATURE AUTHENTIQUE', 'La signature du testament est vraie, mais le signataire a subi des pressions.'),
('007', 'DOCUMENT CACHÉ', 'Un membre de la famille a récupéré un document important avant la mort puis a menti sur l’heure où il l’avait eu.', 'DOCUMENT CACHÉ', 'Un proche a caché un document avant la mort, puis menti sur l’heure à laquelle il l’avait pris.'),
('007', 'FILIATION CACHÉE', 'Un ancien document familial révèle un lien de filiation capable de modifier l’héritage.', 'FILIATION CACHÉE', 'Un document révèle un lien de parenté caché qui pourrait changer l’héritage.'),
('007', 'HÉRITAGE BOULEVERSÉ', 'Après la mort, le testament ne suffit plus à expliquer qui gagne quoi. La dette et la filiation changent le partage.', 'HÉRITAGE BOULEVERSÉ', 'Une dette et un lien de parenté caché peuvent changer le partage de l’héritage.'),
('007', 'PAS DE FAUX TESTAMENT', 'L’expertise écarte une fausse signature. La signature est vraie, même si le contexte ne l’était pas.', 'PAS DE FAUX TESTAMENT', 'La signature est vraie. Elle ne prouve pas que son auteur a signé librement.'),
('008', 'PIÈCE CONNUE TROP TÔT', 'Une personne connaissait une pièce du dossier avant sa déposition officielle.', 'PIÈCE CONNUE TROP TÔT', 'Quelqu’un connaissait une pièce du dossier avant de témoigner.'),
('008', 'CONTACT AVANT AUDITION', 'Un témoin a été contacté avant son audition. La conversation précède sa version officielle.', 'CONTACT AVANT AUDITION', 'Un témoin a reçu un appel avant de donner sa version officielle.'),
('008', 'HEURE RÉELLE', 'Une donnée indépendante place un témoin sur les lieux plus tôt qu’il ne l’a déclaré.', 'HEURE RÉELLE', 'Une preuve place un témoin sur les lieux plus tôt qu’il ne l’a dit.'),
('008', 'FAUTE CACHÉE', 'Un faux horaire sert à cacher une autre faute. Il ne décrit pas le fait principal du dossier.', 'FAUTE CACHÉE', 'Un faux horaire cache une autre faute, sans lien direct avec le fait principal.'),
('008', 'RELATION CACHÉE', 'Des échanges privés confirment une relation secrète qui explique l’un des faux horaires.', 'RELATION CACHÉE', 'Une relation secrète explique pourquoi un témoin a menti sur son horaire.'),
('008', 'UNE PARTIE ÉTAIT VRAIE', 'Une preuve indépendante confirme un élément central d’une déposition pourtant fausse sur un autre point.', 'UNE PARTIE ÉTAIT VRAIE', 'Un témoin a menti sur un point, mais une preuve confirme une autre partie de son récit.'),
('008', 'TROIS MENSONGES DIFFÉRENTS', 'Les mensonges ne portent pas sur le même fait : horaire, pression et vie privée apparaissent séparément dans les preuves.', 'TROIS MENSONGES DIFFÉRENTS', 'Les mensonges portent sur trois sujets différents : un horaire, une pression et une relation cachée.'),
('009', 'REFUS HORODATÉ', 'Le Sujet 17 retire son consentement avant la poursuite du protocole. L’horodatage est incontestable.', 'REFUS HORODATÉ', 'Le Sujet 17 a retiré son accord avant la poursuite de l’expérience. L’heure est enregistrée.'),
('009', 'AMNÉSIE RÉELLE', 'L’amnésie du médecin est réelle et compatible avec sa chute. Elle commence après les décisions contestées.', 'AMNÉSIE RÉELLE', 'Le médecin a réellement perdu la mémoire après sa chute. Les décisions contestées étaient antérieures.'),
('009', 'PROTOCOLE DÉPASSÉ', 'Le protocole officiel n’autorisait pas ce qui a été fait après le retrait du consentement.', 'PROTOCOLE DÉPASSÉ', 'Après le refus du Sujet 17, l’équipe a poursuivi des actes interdits par le protocole.'),
('009', 'ALERTES REÇUES', 'Plusieurs alertes avaient été transmises au responsable institutionnel avant l’incident.', 'ALERTES REÇUES', 'Le responsable du programme avait reçu plusieurs alertes avant l’incident.'),
('009', 'AIDE À LA SORTIE', 'Un membre de l’équipe a aidé le Sujet 17 à chercher une sortie puis a caché ce geste pour protéger son poste.', 'AIDE À LA SORTIE', 'Un membre de l’équipe a aidé le Sujet 17 à chercher une sortie, puis l’a caché pour protéger son emploi.'),
('009', 'NOTE RÉÉCRITE', 'Une note clinique est modifiée après l’incident. La première version est toujours récupérable.', 'NOTE RÉÉCRITE', 'Une note médicale a été modifiée après l’incident. L’ancienne version existe encore.'),
('009', 'DÉCISION AVANT LA CHUTE', 'Les traces écrites montrent que la décision de continuer a été prise avant la chute et avant l’amnésie.', 'DÉCISION AVANT LA CHUTE', 'La décision de poursuivre l’expérience a été prise avant la chute et l’amnésie du médecin.'),
('009', 'PROTÉGER LE PROGRAMME', 'Après l’incident, des échanges internes cherchent d’abord à protéger ORPHÉE avant d’expliquer ce qui s’est passé.', 'PROTÉGER LE PROGRAMME', 'Après l’incident, des messages montrent que l’équipe cherche d’abord à protéger le programme ORPHÉE.'),
('010', 'OUVERTURE 13 H 54', 'Le capteur enregistre une ouverture à 13 h 54. Quelqu’un accède à Nora à cet instant.', 'OUVERTURE 13 H 54', 'La porte de Nora s’ouvre à 13 h 54. Quelqu’un a alors accès à elle.'),
('010', 'BRUITS DERRIÈRE LE MUR', 'Des bruits sont signalés derrière le mur bien avant 13 h 54. Personne ne sait alors avec certitude qu’il s’agit de Nora.', 'BRUITS DERRIÈRE LE MUR', 'Des bruits sont entendus derrière le mur avant 13 h 54. On ignore alors s’ils viennent de Nora.'),
('010', 'AUTRE ACCÈS INUTILISÉ', 'Un autre accès existe, mais il n’est pas utilisé pendant la fenêtre critique.', 'AUTRE ACCÈS INUTILISÉ', 'Une autre entrée existait, mais elle n’a pas été utilisée au moment critique.'),
('010', 'DEUX MOMENTS', 'Les éléments séparent deux moments : l’enfermement initial, puis l’ouverture et la fermeture de 13 h 54.', 'DEUX MOMENTS', 'Nora a d’abord été enfermée. Sa porte a ensuite été ouverte puis refermée à 13 h 54.'),
('010', 'DEUX PRÉSENCES', 'Les preuves n’imposent pas que la personne qui enferme Nora soit celle qui la voit vivante plus tard.', 'DEUX PRÉSENCES', 'Rien ne prouve que la personne qui a enfermé Nora est celle qui l’a revue vivante.'),
('011', 'ORDRE INCOMPLET', 'L’ordre écrit autorise l’opération, mais plusieurs contraintes connues sur place n’y figurent pas.', 'ORDRE INCOMPLET', 'L’ordre officiel ne mentionne pas plusieurs risques déjà connus des soldats sur place.'),
('011', 'ORDRE DÉPASSÉ', 'Sur le terrain, une unité va au-delà de ce que l’ordre autorisait.', 'ORDRE DÉPASSÉ', 'Une unité militaire a fait plus que ce que l’ordre autorisait.'),
('011', 'ALERTES FRAGMENTÉES', 'Les premiers signalements arrivent fragmentés. Le commandement et le terrain ne disposent pas des mêmes informations.', 'ALERTES FRAGMENTÉES', 'Les chefs et les soldats n’ont pas reçu les mêmes alertes au même moment.'),
('011', '36 HEURES DE RETARD', 'Trente-six heures séparent le premier signalement sérieux et l’arrêt effectif de l’opération.', '36 HEURES DE RETARD', 'Il s’est écoulé 36 heures entre la première alerte grave et l’arrêt de l’opération.'),
('011', 'POUVOIR D’ARRÊT', 'Un responsable avait le pouvoir d’interrompre une partie de l’opération avant l’arrêt final.', 'POUVOIR D’ARRÊT', 'Un responsable pouvait interrompre une partie de l’opération avant son arrêt final.'),
('011', 'ARRÊT TROP TARD', 'Au moment où l’ordre d’arrêt tombe, plusieurs morts et destructions ont déjà été signalées.', 'ARRÊT TROP TARD', 'Quand l’opération a été arrêtée, des morts et des destructions avaient déjà été signalés.'),
('011', 'FAITS MINIMISÉS', 'La version finale du rapport réduit le dépassement commis sur le terrain par rapport à la première version.', 'FAITS MINIMISÉS', 'Le rapport final minimise les actes commis au-delà des ordres initiaux.'),
('012', 'TÉLÉPHONE CONFISQUÉ', 'Le téléphone de Sacha est éteint manuellement à 21h18 puis rangé dans un casier réservé aux responsables.', 'TÉLÉPHONE CONFISQUÉ', 'À 21 h 18, quelqu’un éteint le téléphone de Sacha et le range dans un casier réservé aux responsables.'),
('012', 'VERROU IMPARFAIT', 'Le second verrou a été engagé puis laissé imparfaitement fermé.', 'VERROU IMPARFAIT', 'Le deuxième verrou a été fermé, mais mal enclenché.'),
('012', 'AUCUN DROIT DE LE RETENIR', 'Le règlement prévoit une sanction symbolique. Il n’autorise ni coups ni enfermement.', 'AUCUN DROIT DE LE RETENIR', 'Le règlement n’autorisait personne à frapper ou à enfermer Sacha.'),
('012', 'ANCIENNES RÉTENTIONS', 'Un ancien membre décrit d’autres personnes retenues contre leur volonté sous couvert de « recentrage ».', 'ANCIENNES RÉTENTIONS', 'Un ancien membre dit que d’autres personnes ont déjà été enfermées au nom du « recentrage ».'),
('012', 'CLÉ DE SERVICE', 'La clé principale a circulé entre deux personnes sans trace du dernier usage.', 'CLÉ DE SERVICE', 'Deux personnes se sont passé la clé principale. On ignore qui l’a utilisée en dernier.'),
('012', 'IL SORT SANS CASSER LA PORTE', 'Sacha s’échappe sans forcer la porte. Au moins un verrou n’était plus correctement engagé.', 'IL SORT SANS CASSER LA PORTE', 'Sacha s’est échappé sans forcer la porte : au moins un verrou était mal fermé.'),
('013', 'ANGLE BALISTIQUE', 'La trajectoire impose une fenêtre de moins de 90 secondes depuis un toit technique.', 'ANGLE BALISTIQUE', 'Le tir depuis le toit n’a pu durer que moins de 90 secondes.'),
('013', 'MAINTENANCE FICTIVE', 'Une maintenance enregistrée n’a jamais eu lieu.', 'MAINTENANCE FICTIVE', 'Une maintenance est inscrite au registre, mais personne ne l’a effectuée.'),
('013', 'VÉHICULE RELAIS', 'Un utilitaire loué sous identité intermédiaire stationne près du bâtiment.', 'VÉHICULE RELAIS', 'Une camionnette louée par un intermédiaire est garée près du bâtiment.'),
('013', 'PAIEMENT FRACTIONNÉ', 'Trois virements convergent vers une même société écran.', 'PAIEMENT FRACTIONNÉ', 'Trois virements arrivent sur le compte de la même société écran.'),
('013', 'BADGE NEUTRALISÉ', 'Un badge est neutralisé onze minutes puis réactivé.', 'BADGE NEUTRALISÉ', 'Un badge a été désactivé pendant onze minutes, puis réactivé.'),
('013', 'ARME DÉMONTÉE', 'Une pièce de l’arme est retrouvée loin du point de tir.', 'ARME DÉMONTÉE', 'Une pièce de l’arme a été retrouvée loin du lieu du tir.'),
('013', 'MESSAGE PERSEUS', 'Un message chiffré ne contient qu’une heure et le mot « fenêtre ».', 'MESSAGE PERSEUS', 'Un message chiffré de PERSEUS contient une heure et le mot « fenêtre ».'),
('013', 'FAUSSE PLAQUE', 'La plaque du véhicule relais est un duplicata.', 'FAUSSE PLAQUE', 'La plaque de la camionnette est une copie d’une autre plaque.'),
('013', 'RAPPORT RETOUCHÉ', 'Le journal de sécurité est réexporté dix-sept minutes après le tir.', 'RAPPORT RETOUCHÉ', 'Le journal de sécurité a été exporté de nouveau 17 minutes après le tir.'),
('013', 'APPEL DE 14 SECONDES', 'Un téléphone jetable contacte un numéro professionnel de sécurité avant le déplacement.', 'APPEL DE 14 SECONDES', 'Un téléphone jetable a appelé un numéro professionnel de sécurité pendant 14 secondes.'),
('013', 'CHAÎNE CLOISONNÉE', 'Les trois maillons communiquaient par intermédiaires et ne se connaissaient pas tous.', 'CHAÎNE CLOISONNÉE', 'Les trois acteurs de l’opération passaient par des intermédiaires. Ils ne se connaissaient pas tous.'),
('014', 'EXPORT FRAGMENTÉ', 'Les pages ont été exportées à plusieurs dates.', 'EXPORT FRAGMENTÉ', 'Les pages du dossier ont été exportées à plusieurs dates.'),
('014', 'JOURNAUX RETOUCHÉS', 'Des lignes d’audit sont réécrites après la découverte.', 'JOURNAUX RETOUCHÉS', 'Des lignes du journal informatique ont été modifiées après la découverte de la fuite.'),
('014', 'ONZE IDENTITÉS', 'La fuite contient exactement onze informateurs et des données familiales.', 'ONZE IDENTITÉS', 'La fuite contient les identités de onze informateurs et des données sur leurs familles.'),
('014', 'COPIE HORS RÉSEAU', 'Une clé chiffrée est montée puis retirée sans preuve de destruction.', 'COPIE HORS RÉSEAU', 'Une clé chiffrée a été utilisée puis retirée. Rien ne prouve que son contenu a été détruit.'),
('014', 'RENDEZ-VOUS DIPLOMATIQUE', 'Un téléphone secondaire borne près d’un hôtel fréquenté par une délégation étrangère.', 'RENDEZ-VOUS DIPLOMATIQUE', 'Un téléphone secondaire a été repéré près d’un hôtel fréquenté par une délégation étrangère.'),
('014', 'PAGE MANQUANTE', 'Une page absente du premier export existe dans la fuite finale.', 'PAGE MANQUANTE', 'Une page absente du premier export figure dans la fuite finale.'),
('014', 'AUDIT INTERNE', 'Une autre faille de sécurité était connue mais non déclarée.', 'AUDIT INTERNE', 'Une autre faille de sécurité était connue, mais n’avait pas été signalée.'),
('014', 'PAIEMENT INDIRECT', 'Un transfert coïncide avec la reconstitution de la liste.', 'PAIEMENT INDIRECT', 'Un transfert d’argent coïncide avec la reconstitution de la liste d’informateurs.'),
('014', 'FUSION DE SOURCES', 'Le fichier final provient d’au moins deux sources numériques.', 'FUSION DE SOURCES', 'Le fichier diffusé rassemble des données provenant d’au moins deux sources.'),
('014', 'DEUX OPÉRATIONS DISTINCTES', 'Les expertises séparent clairement la falsification des logs de la transmission finale des données.', 'DEUX OPÉRATIONS DISTINCTES', 'La modification des journaux et la fuite finale des données sont deux actions distinctes.'),
('015', 'IL SIGNE QUAND MÊME', 'Le même clinicien écrit que la poursuite est dangereuse, puis signe pour continuer.', 'IL SIGNE QUAND MÊME', 'Le clinicien a écrit qu’il était dangereux de continuer, puis a signé pour poursuivre.'),
('015', 'RÉUNION BUDGÉTAIRE', 'Une réunion sur le financement a lieu le jour du refus.', 'RÉUNION BUDGÉTAIRE', 'Une réunion sur le financement a eu lieu le jour où l’arrêt du programme a été refusé.'),
('015', 'DOSSIER MODIFIÉ APRÈS LA MORT', 'Après la mort, une note clinique n’a plus le même contenu que sa première version.', 'DOSSIER MODIFIÉ APRÈS LA MORT', 'Une note médicale a été modifiée après la mort du patient.'),
('015', 'AUCUN COMITÉ D’ÉTHIQUE', 'Malgré les alertes, le comité d’éthique n’est jamais saisi.', 'AUCUN COMITÉ D’ÉTHIQUE', 'Malgré plusieurs alertes, personne n’a saisi le comité d’éthique.'),
('015', 'DOSSIER RETARDÉ', 'Un document externe est transmis avec vingt-six heures de retard.', 'DOSSIER RETARDÉ', 'Un document destiné à l’extérieur a été envoyé avec 26 heures de retard.'),
('015', 'RÉÉVALUATION APRÈS LA CRISE', 'Une demande de réévaluation existe. Elle n’arrive qu’après une crise majeure.', 'RÉÉVALUATION APRÈS LA CRISE', 'Le patient subit une crise grave avant qu’une réévaluation ne soit demandée.'),
('015', 'ALERTES EFFACÉES APRÈS LA MORT', 'Après la mort, plusieurs alertes sont atténuées ou rendues moins visibles dans la version finale du dossier.', 'ALERTES EFFACÉES APRÈS LA MORT', 'Après la mort du patient, des alertes ont été atténuées dans son dossier.'),
('016', 'SÉDATIF', 'Le produit provient d’un lot détourné.', 'SÉDATIF', 'Le sédatif vient d’un lot détourné.'),
('016', 'DEUX BADGES', 'Deux badges accèdent au dernier étage.', 'DEUX BADGES', 'Deux badges différents ont ouvert l’accès au dernier étage.'),
('016', 'MESSAGE « STOP »', 'Un message demandant d’arrêter est envoyé avant le décès.', 'MESSAGE « STOP »', 'Un message demandant d’arrêter a été envoyé avant la mort.'),
('016', 'AUDIO HORS IMAGE', 'Quelques secondes captent deux voix après la coupure.', 'AUDIO HORS IMAGE', 'Un court enregistrement sonore capte deux voix après la coupure de la vidéo.'),
('016', 'CORPS DÉPLACÉ', 'Le meurtre n’a pas eu lieu exactement à l’endroit filmé.', 'CORPS DÉPLACÉ', 'La victime n’a pas été tuée exactement à l’endroit montré dans la vidéo.'),
('016', 'PAIEMENT DU PRODUIT', 'Le sédatif est relié à un intermédiaire, pas directement au tueur.', 'PAIEMENT DU PRODUIT', 'Le sédatif est relié à un intermédiaire, pas directement au meurtrier.'),
('016', 'CAMÉRA DU PALIER', 'Une silhouette reste seule au dernier étage après le départ d’un autre participant.', 'CAMÉRA DU PALIER', 'Après le départ d’un participant, une silhouette reste seule au dernier étage.'),
('016', 'EFFACEMENT CLOUD', 'La vidéo est effacée après la découverte du corps par un compte distinct du filmeur.', 'EFFACEMENT CLOUD', 'La vidéo a été supprimée après la découverte du corps, par un autre compte que celui du filmeur.'),
('017', 'DEUX OTAGES VIVANTS', 'Une image de péage montre les deux personnes enlevées encore vivantes peu après leur disparition.', 'DEUX OTAGES VIVANTS', 'Une caméra de péage montre les deux otages encore vivants après leur enlèvement.'),
('017', 'ENTREPÔT 4B', 'Le téléphone du survivant s’éteint près d’un entrepôt lié à une société écran du réseau.', 'ENTREPÔT 4B', 'Le téléphone du survivant s’éteint près d’un entrepôt lié au réseau.'),
('017', 'MORT SOUS CONTRAINTE', 'L’examen médico-légal relie la mort à une contrainte physique prolongée. Ce n’est pas un malaise spontané.', 'MORT SOUS CONTRAINTE', 'L’autopsie relie la mort à une contrainte physique prolongée, pas à un malaise.'),
('017', 'LE SURVIVANT RESSORT SEUL', 'Quelques heures plus tard, une caméra montre le survivant dans un autre véhicule. La victime n’y est pas.', 'LE SURVIVANT RESSORT SEUL', 'Une caméra montre le survivant repartir seul dans un autre véhicule.'),
('017', 'APPEL DE 19 SECONDES', 'Un appel de 19 secondes part pendant la dégradation de l’état de la victime. Le destinataire reste inconnu.', 'APPEL DE 19 SECONDES', 'Pendant que la victime va de plus en plus mal, un appel de 19 secondes est passé. On ignore à qui.'),
('017', '« IL RESPIRE MAL »', 'Un audio capte : « Il respire mal. » Une voix répond d’attendre avant de bouger.', '« IL RESPIRE MAL »', 'Un enregistrement capte « Il respire mal ». Une autre voix répond d’attendre.'),
('017', 'PAIEMENT APRÈS LA MORT', 'Un paiement vers un intermédiaire part après l’heure probable du décès, avant la libération du survivant.', 'PAIEMENT APRÈS LA MORT', 'Un intermédiaire reçoit un paiement après la mort, mais avant la libération du survivant.'),
('017', 'MESSAGES EFFACÉS APRÈS LA MORT', 'Deux messages sont supprimés à distance après la mort. Leur contenu complet n’est pas récupéré.', 'MESSAGES EFFACÉS APRÈS LA MORT', 'Deux messages ont été effacés à distance après la mort. Leur contenu reste inconnu.'),
('017', 'MENACE SUR UN PROCHE', 'Le survivant dit qu’on lui a ordonné de se taire sous menace contre un proche. Un contact de la même nuit confirme la pression.', 'MENACE SUR UN PROCHE', 'Le survivant dit qu’un proche a été menacé pour le faire taire. Un contact de la nuit confirme la pression.'),
('017', 'D’ABORD LA MORT, ENSUITE LE SILENCE', 'La détresse mortelle commence avant l’effacement des preuves et avant les menaces imposées au survivant.', 'D’ABORD LA MORT, ENSUITE LE SILENCE', 'La victime était déjà en danger de mort avant l’effacement des preuves et les menaces contre le survivant.'),
('018', 'ASSIETTES APRÈS LA MORT', 'La vaisselle est disposée après l’heure probable du décès.', 'ASSIETTES APRÈS LA MORT', 'Les assiettes ont été placées sur la table après la mort.'),
('018', 'TRACE SOUS LA TABLE', 'Une trace de lutte est masquée par une nappe repositionnée.', 'TRACE SOUS LA TABLE', 'Une nappe déplacée cache une trace de lutte sous la table.'),
('018', 'ARGENT MANQUANT', 'Une petite somme disparaît sans lien direct avec le corps.', 'ARGENT MANQUANT', 'De l’argent a disparu, sans lien direct établi avec la mort.'),
('018', 'OBJET ESSUYÉ', 'Un objet décoratif est nettoyé sans avoir servi d’arme.', 'OBJET ESSUYÉ', 'Un objet décoratif a été essuyé, mais il n’a pas servi d’arme.'),
('018', 'DEUX SEMELLES', 'Deux passages distincts correspondent à des semelles différentes.', 'DEUX SEMELLES', 'Deux traces de chaussures différentes montrent deux passages.'),
('018', 'MEUBLE DÉPLACÉ', 'Un capteur signale un meuble déplacé après le décès.', 'MEUBLE DÉPLACÉ', 'Un capteur montre qu’un meuble a été déplacé après le décès.'),
('018', 'PHOTO ANCIENNE', 'Une photo explique la symbolique d’une assiette sans expliquer la mort.', 'PHOTO ANCIENNE', 'Une vieille photo explique pourquoi une assiette a été posée, mais pas la mort.'),
('018', 'TRACE DE VOL', 'Une empreinte se trouve sur le tiroir d’argent mais pas autour du corps.', 'TRACE DE VOL', 'Une empreinte est trouvée sur le tiroir d’argent, mais pas près du corps.'),
('018', 'SANG MASQUÉ', 'Une microprojection est cachée par un élément posé plus tard.', 'SANG MASQUÉ', 'Une petite trace de sang a été cachée par un objet posé plus tard.'),
('018', 'SCÈNE MODIFIÉE APRÈS LA MORT', 'La mort précède le déplacement du mobilier et la mise en place des assiettes.', 'SCÈNE MODIFIÉE APRÈS LA MORT', 'Le mobilier et les assiettes ont été disposés après le décès.'),
('019', 'LE DOSSIER ATTENDU', 'La victime devait remettre des documents financiers au gala. Les copies récupérées ne concordent pas toutes sur les opérations concernées.', 'LE DOSSIER ATTENDU', 'La victime devait remettre des documents financiers au gala. Les copies trouvées ne correspondent pas toutes.'),
('019', 'LE DISPOSITIF MODIFIÉ', 'Des trajets et des accès techniques ont été modifiés pendant le gala. Les relevés ne précisent pas encore qui a demandé ces changements.', 'LE DISPOSITIF MODIFIÉ', 'Pendant le gala, des trajets et des accès ont changé. On ignore qui l’a demandé.'),
('019', 'LES COPIES CONTRADICTOIRES', 'Plusieurs versions des mêmes registres financiers circulent. Elles ne présentent pas toutes les mêmes informations.', 'LES COPIES CONTRADICTOIRES', 'Plusieurs copies des mêmes comptes ne contiennent pas les mêmes informations.'),
('020', 'UN BÂTIMENT OCCUPÉ', 'Les plans du Bal des Fondateurs prévoient plusieurs issues secondaires. Les journaux montrent que certaines ont été ouvertes avec retard.', 'SORTIES OUVERTES TROP TARD', 'Plusieurs sorties de secours du Bal des Fondateurs ont été ouvertes avec retard.'),
('020', 'DES RÉSERVES À CONTRÔLER', 'Des travaux de maintenance étaient encore en cours dans les locaux techniques avant l’incendie. Leur rôle exact dans sa propagation reste incertain.', 'TRAVAUX NON TERMINÉS', 'Des travaux étaient encore en cours avant l’incendie. Leur rôle dans la propagation reste incertain.'),
('020', 'UNE CHRONOLOGIE À VÉRIFIER', 'Les journaux du poste de sécurité montrent un délai entre les premiers signaux et l’alarme générale.', 'ALARME RETARDÉE', 'L’alarme générale a été déclenchée après les premiers signaux de danger.'),
('021', 'LE TRAJET', 'Le parcours de l’enveloppe comporte une rupture de quarante-deux minutes. Deux personnes pouvaient expliquer cette fenêtre.', 'LE TRAJET', 'Le trajet de l’enveloppe comporte 42 minutes sans trace. Deux personnes peuvent expliquer ce délai.'),
('021', 'LA COMPTABILITÉ', 'Le montant disparu ne correspond pas exactement aux sommes collectées. Une seconde destination financière existait.', 'LA COMPTABILITÉ', 'Les comptes ne correspondent pas à tout l’argent récolté. Une partie est allée ailleurs.'),
('021', 'LE CERCLE', 'L’information sur la destination finale n’était connue que d’un groupe très réduit. Toute révélation permet donc à la Famiglia de resserrer ses soupçons.', 'DESTINATION SECRÈTE', 'Très peu de personnes connaissaient la destination finale de l’enveloppe.'),
('022', 'LE MOT MANQUANT', 'Aucun témoin n’a entendu un ordre explicite de tuer. Plusieurs ont toutefois entendu des formulations qui pouvaient être comprises comme une autorisation.', 'LE MOT MANQUANT', 'Personne n’a entendu d’ordre de tuer. Certaines paroles pouvaient pourtant être comprises comme une permission.'),
('022', 'LE VÉHICULE', 'Le véhicule utilisé après le meurtre appartenait au groupe. Trois personnes savaient qui l’avait emprunté.', 'LE VÉHICULE', 'Le groupe possédait le véhicule utilisé après le meurtre. Trois personnes savaient qui l’avait emprunté.'),
('022', 'LE SILENCE ORGANISÉ', 'Après les faits, plusieurs versions ont été harmonisées. Cette coordination ne prouve pas l’ordre initial, mais elle prouve une volonté de dissimulation.', 'LE SILENCE ORGANISÉ', 'Après le meurtre, des membres du groupe ont accordé leurs récits. On ignore encore qui a donné l’ordre.'),
('023', 'LA CHAISE VIDE', 'Le représentant absent avait rencontré séparément deux camps avant la réunion. Son absence n’est probablement pas un simple retard.', 'LA CHAISE VIDE', 'Avant la réunion, le représentant absent avait rencontré les deux camps séparément.'),
('023', 'L’ITINÉRAIRE D’ADRIANO', 'Très peu de personnes connaissaient le déplacement d’Adriano. La fuite est donc interne ou issue d’un proche des négociations.', 'L’ITINÉRAIRE D’ADRIANO', 'Très peu de personnes connaissaient le trajet d’Adriano. L’information a pu circuler parmi leurs proches.'),
('023', 'L’APPEL', 'Un appel confirme qu’Adriano Verri a été blessé. Il ne permet pas d’établir qui l’a attaqué ni la gravité exacte de ses blessures.', 'ADRIANO BLESSÉ', 'Un appel confirme qu’Adriano Verri est blessé. On ignore qui l’a attaqué et la gravité de ses blessures.'),
('024', 'CE QUI EST DÉJÀ CONNU', 'Plusieurs faits que le détenu propose de révéler figurent déjà dans les pièces saisies par les enquêteurs.', 'CE QUI EST DÉJÀ CONNU', 'Paolo Serra propose des informations que les enquêteurs possèdent déjà en partie.'),
('024', 'LA PREUVE NOUVELLE', 'Une information inconnue des enquêteurs relie directement une opération au cercle supérieur. Sa valeur judiciaire est forte et son danger mafieux l’est tout autant.', 'LA PREUVE NOUVELLE', 'Paolo Serra connaît un fait nouveau qui relie une opération à la direction de la Famiglia.'),
('024', 'LA PROTECTION', 'Le détenu réclame une protection en échange de ses informations. Sa demande ne prouve pas qu’un accord a été accepté.', 'PROTECTION DEMANDÉE', 'Paolo Serra demande une protection. Les documents ne disent pas si elle lui a été accordée.'),
('025', 'LES ORDRES', 'Certaines décisions de Vittorio portent sa validation. D’autres lui sont attribuées sans qu’un ordre écrit ait été retrouvé.', 'ORDRES ATTRIBUÉS AU DON', 'Vittorio a approuvé certaines décisions. D’autres lui sont attribuées sans preuve qu’il les ait ordonnées.'),
('025', 'LES DÉCISIONS DU DON', 'Les décisions de protection et de sanction prises au sommet ne sont pas toutes accompagnées d’une instruction écrite.', 'SANCTIONS SANS ORDRE', 'Des membres ont été protégés ou punis au nom de Vittorio. Pour certains cas, aucun ordre de lui n’a été retrouvé.'),
('025', 'LE SOMMET', 'Des hommes de Vittorio ont commis des violences sans ordre écrit. D’autres actes sont directement liés à ses validations.', 'PAIEMENTS ET VIOLENCES', 'Des comptes relient des paiements à Vittorio. Ils ne disent pas toujours qui a demandé les violences.'),
('026', 'SECTEUR PERDU', 'Un nouveau secteur de la ville n’est plus sous contrôle des autorités. Plusieurs communications institutionnelles sont interrompues.', 'SECTEUR PERDU', 'Un secteur de la ville échappe aux autorités. Des communications avec cette zone sont coupées.'),
('026', 'DÉCÈS CONFIRMÉS', 'Une source qui devait être entendue ne répondra plus. Son décès vient d’être confirmé.', 'DÉCÈS CONFIRMÉS', 'La mort d’une source attendue par la Grey Room vient d’être confirmée.'),
('026', 'CHAÎNE ENCORE ACTIVE', 'Des éléments indépendants confirment qu’une structure extérieure continue de fonctionner malgré les arrestations.', 'CHAÎNE ENCORE ACTIVE', 'Le réseau continue de fonctionner malgré les arrestations.'),
('026', 'MESSAGE ANTÉRIEUR', 'Un message transmis avant les arrestations indique que la continuité du groupe avait été anticipée.', 'MESSAGE ANTÉRIEUR', 'Un message envoyé avant les arrestations montre que le groupe avait prévu de poursuivre ses activités.'),
('026', 'LE PRISONNIER PANIQUE', 'L’un des détenus demande soudain si le bâtiment sera évacué. Rien dans l’interrogatoire public ne lui a encore annoncé la dégradation du périmètre.', 'LE PRISONNIER PANIQUE', 'Un détenu demande si le bâtiment va être évacué, alors que personne ne lui a annoncé le danger.'),
('026', 'AUTORITÉ SYMBOLIQUE', 'Plusieurs sources distinguent le commandement matériel d’une figure idéologique dont les consignes continuent d’être suivies.', 'AUTORITÉ SYMBOLIQUE', 'Des sources disent que le chef militaire et la figure idéologique du groupe ne sont pas les mêmes.'),
('026', 'PÉRIMÈTRE RÉDUIT', 'Les autorités réduisent la zone qu’elles garantissent autour de la Grey Room. L’enquête continue.', 'PÉRIMÈTRE RÉDUIT', 'Les autorités ne garantissent plus la sécurité de toute la zone autour de la Grey Room.'),
('026', 'TÉMOIN INACCESSIBLE', 'Un témoin qui devait confirmer une partie de la chaîne de responsabilités devient inaccessible après la perte d’un secteur.', 'TÉMOIN INACCESSIBLE', 'Après la perte d’un secteur, un témoin attendu ne peut plus être joint.'),
('026', 'LA GREY ROOM EST CONCERNÉE', 'Le recoupement final confirme que le dispositif extérieur ne cherche pas seulement à tenir la ville : la chute du périmètre judiciaire fait partie de ses objectifs.', 'LA GREY ROOM EST CONCERNÉE', 'Le groupe cherche aussi à faire tomber la protection judiciaire autour de la Grey Room.'),
('027', 'ÉVACUATION INCOMPLÈTE', 'Les autorités confirment que des civils n’ont pas tous quitté la zone contestée.', 'ÉVACUATION INCOMPLÈTE', 'Des civils sont encore présents dans la zone contestée.'),
('027', 'PRÉSENCE RÉCENTE', 'Deux sources placent plusieurs cadres de l’organisation dans la même zone au cours des dernières heures, sans prouver qu’ils y sont encore.', 'PRÉSENCE RÉCENTE', 'Deux sources ont vu récemment des cadres du FDR dans la zone. Ils peuvent déjà être partis.'),
('027', 'DÉTENTION CLANDESTINE', 'Des témoins décrivent des mauvais traitements dans l’appareil de détention du FDR où travaillait l’un des suspects.', 'DÉTENTION CLANDESTINE', 'Des prisonniers ont été maltraités dans le service où travaillait l’agent chargé des détentions du FDR.'),
('027', 'RUPTURE INTERNE', 'Des documents saisis montrent une lutte récente entre deux factions du même mouvement.', 'RUPTURE INTERNE', 'Des documents montrent que deux factions du FDR se disputent le pouvoir.'),
('027', 'SOURCE TROP PRÉCISE', 'Le cadre supérieur du FDR donne des détails précis sur les dirigeants rivaux, mais presque rien sur ses propres alliés.', 'SOURCE TROP PRÉCISE', 'Le cadre supérieur du FDR décrit en détail ses rivaux, mais parle peu de ses alliés.'),
('027', 'OTAGES POSSIBLES', 'Une source indépendante estime que des personnes détenues peuvent encore se trouver dans la zone. Leur nombre est inconnu.', 'OTAGES POSSIBLES', 'Une source dit que des otages sont peut-être encore retenus dans la zone. Leur nombre reste inconnu.'),
('027', 'DEUX CENTRES DE POUVOIR', 'Le renseignement conclut que l’organisation ne possède plus un commandement parfaitement unifié : deux pôles se disputent l’autorité.', 'DEUX CENTRES DE POUVOIR', 'Deux groupes du FDR se disputent maintenant le commandement.'),
('027', 'INTÉRÊT PERSONNEL', 'Un échange ancien montre que le cadre supérieur du FDR considérait déjà ces dirigeants comme ses rivaux.', 'INTÉRÊT PERSONNEL', 'Un ancien échange montre que le cadre supérieur du FDR voyait déjà ces chefs comme ses rivaux.'),
('027', 'LA VÉRITÉ PEUT ÊTRE UNE ARME', 'Les renseignements du cadre supérieur sont souvent exacts, mais concernent surtout ses rivaux. Ses propres alliés y apparaissent peu.', 'LA VÉRITÉ PEUT ÊTRE UNE ARME', 'Les informations du cadre supérieur sont souvent justes, mais concernent surtout ses rivaux.'),
('028', 'CAPITAINE — DÉCÉDÉ', 'L’officier qui assurait une liaison extérieure est déclaré mort. La Grey Room perd un interlocuteur, pas sa mission.', 'CAPITAINE — DÉCÉDÉ', 'Le capitaine chargé du lien avec l’extérieur est mort.'),
('028', 'SOURCE INJOIGNABLE', 'Une source située dans un secteur récemment perdu cesse de répondre. Son statut reste inconnu.', 'SOURCE INJOIGNABLE', 'Une source ne répond plus depuis la perte d’un secteur. On ignore ce qui lui est arrivé.'),
('028', 'ACCÈS ANTÉRIEUR', 'Une personne liée au réseau avait un accès administratif au périmètre avant sa fermeture complète.', 'ACCÈS ANTÉRIEUR', 'Une personne liée au réseau disposait d’un accès administratif avant la fermeture du périmètre.'),
('028', 'PRISONNIERS SACRIFIABLES', 'Un document interne indique que les membres capturés ne doivent plus être considérés comme récupérables.', 'PRISONNIERS SACRIFIABLES', 'Un document du groupe indique que ses membres capturés ne seront pas récupérés.'),
('028', 'COMMUNICATIONS INTERMITTENTES', 'La Grey Room perd puis retrouve sa liaison extérieure. Plusieurs informations arrivent avec retard.', 'COMMUNICATIONS INTERMITTENTES', 'Les communications de la Grey Room coupent par moments. Des informations arrivent en retard.'),
('028', 'COOPÉRATION CONCORDANTE', 'Deux suspects donnent séparément des éléments compatibles sur la manière dont le groupe abandonne ses membres capturés.', 'COOPÉRATION CONCORDANTE', 'Deux détenus décrivent séparément comment le groupe abandonne ses membres capturés.'),
('028', 'AUCUNE DEMANDE DE PROTECTION', 'Le cadre resté fidèle au FDR ne demande aucune protection malgré la menace sur le périmètre. Il affirme pourtant n’être qu’un exécutant.', 'AUCUNE DEMANDE DE PROTECTION', 'Le cadre fidèle au FDR ne demande ni protection ni évacuation malgré la menace.'),
('028', 'PRÉSENCE INTÉRIEURE PLAUSIBLE', 'Plusieurs signaux indépendants rendent crédible l’existence d’une cellule clandestine déjà présente dans le périmètre avant sa fermeture.', 'PRÉSENCE INTÉRIEURE PLAUSIBLE', 'Des indices suggèrent qu’une cellule du groupe était déjà à l’intérieur du périmètre.'),
('028', 'DÉCÈS CONFIRMÉ', 'La source précédemment injoignable est désormais déclarée morte. L’information qu’elle devait confirmer devra être établie autrement.', 'DÉCÈS CONFIRMÉ', 'La source qui ne répondait plus est maintenant déclarée morte.'),
('028', 'DERNIER PÉRIMÈTRE', 'La protection extérieure atteint son niveau critique. L’enquête continue, mais aucune sortie ne peut plus être considérée comme garantie.', 'DERNIER PÉRIMÈTRE', 'La protection extérieure est presque épuisée. Aucune sortie ne peut être garantie.'),
('029', 'PAIEMENT APRÈS LES FAITS', 'Un transfert financier effectué après l’exécution relie l’intermédiaire financier au réseau.', 'PAIEMENT APRÈS LES FAITS', 'Un virement après une exécution relie l’intermédiaire financier au cartel.'),
('029', 'ORDRE AMBIGU', 'Le responsable local a envoyé un message demandant de « faire peur », sans préciser jusqu’où aller.', 'ORDRE AMBIGU', 'Le responsable local a écrit « faire peur ». Il n’a pas précisé jusqu’où aller.'),
('029', 'COOPÉRATION', 'L’exécutant devenu coopérant a indiqué un lieu dont l’existence a été vérifiée.', 'COOPÉRATION', 'L’exécutant donne un lieu. Les enquêteurs confirment qu’il existe.'),
('029', 'REPRÉSAILLES', 'Une menace vise l’équipe d’enquête sans révéler qui l’a ordonnée.', 'REPRÉSAILLES', 'L’équipe d’enquête reçoit des menaces, mais on ignore qui les a ordonnées.'),
('029', 'SECONDE VICTIME', 'Une victime non déclarée est reliée à l’exécutant.', 'SECONDE VICTIME', 'Une autre victime est reliée à l’exécutant. Elle n’avait pas été déclarée.'),
('029', 'CHAÎNE DE DÉCISION', 'Les derniers éléments distinguent l’ordre initial, l’escalade et l’exécution matérielle.', 'CHAÎNE DE DÉCISION', 'Les preuves séparent l’ordre d’intimider, la montée de violence et l’exécution.'),
('030', 'P01 — MAIN COURANTE', '03:07 appel; 03:18 patrouilles; 03:32 renforts aux issues; 03:55 unités spécialisées; 04:19 tir isolé entendu; 04:25 reddition de trois assaillants.', 'P01 — MAIN COURANTE', '03 h 07 : appel. 03 h 18 : patrouilles. 03 h 32 : renforts. 03 h 55 : unités spéciales. 04 h 19 : tir. 04 h 25 : reddition.'),
('030', 'P02 — BILAN MÉDICO-LÉGAL', 'Vingt gardes et les occupants de la résidence ont été tués. Deux commandos meurent face aux gardes, quatre face aux forces spéciales, un septième hors combat.', 'P02 — BILAN MÉDICO-LÉGAL', 'Vingt gardes et les occupants sont tués. Deux assaillants meurent face aux gardes, quatre face aux unités spéciales, un septième est hors combat.'),
('030', 'P03 — MESSAGE 03:17', 'Un terminal transmet « Le dossier n''est plus au coffre. Vérifiez l''annexe. » Ce message n''atteste pas que REG-118 ait déjà été découvert.', 'P03 — MESSAGE 03:17', 'À 03 h 17, un message dit : « Le dossier n’est plus au coffre. Vérifiez l’annexe. » Il ne prouve pas que REG-118 a été trouvé.'),
('030', 'P20 — INDEX REG-118', 'Un inventaire antérieur à l''attaque référence F-09, J-04, O-06, AC-17 et C-42. Il ne contient pas la liste détruite.', 'P20 — INDEX REG-118', 'Un inventaire ancien cite F-09, J-04, O-06, AC-17 et C-42. Il ne contient pas la liste REG-118 détruite.'),
('030', 'P10 — ARCHIVE C-42', 'Un document administratif antérieur à l''assaut relie F-09, J-04 et AC-17 par l''intermédiaire Rafael Córdova.', 'P10 — ARCHIVE C-42', 'Avant l’assaut, une archive C-42 relie F-09, J-04 et AC-17 à Rafael Córdova.'),
('030', 'P04 — SCELLÉ I-14', 'Une chemise vide AC-17 est photographiée à 05:14 au seuil du cabinet C-2, puis mise sous scellé G-14 à 05:18.', 'P04 — SCELLÉ I-14', 'La chemise vide AC-17 est photographiée à 05 h 14, puis placée sous scellé G-14 à 05 h 18.'),
('030', 'P05/P06 — COPIE CONTESTÉE', 'La copie de travail I-14 contient une métadonnée contradictoire avec la chaîne de conservation. Une discordance prouve une altération, pas automatiquement son auteur.', 'P05/P06 — COPIE CONTESTÉE', 'La copie I-14 ne correspond pas au registre des scellés. Elle a été modifiée, mais on ignore par qui.'),
('030', 'P11 — FINANCEMENT F-09', 'Des factures de campagne sans prestations suffisamment justifiées sont associées au bureau de Camila Serrano. Le bénéfice de la campagne Valdés ne prouve pas sa connaissance personnelle.', 'P11 — FINANCEMENT F-09', 'Des factures mal justifiées sont liées au bureau de Camila Serrano. Rien ne prouve que Valdés le savait.'),
('030', 'P12 — PROCÉDURE J-04', 'Un calendrier judiciaire a été modifié et une réquisition retirée. Des actes de Rojas et Beltrán sont documentés; la corruption personnelle reste à établir.', 'P12 — PROCÉDURE J-04', 'Un calendrier judiciaire a changé et une réquisition a disparu. Des actes de Rojas et Beltrán sont connus, pas leur corruption.'),
('030', 'P09 — SEPTIÈME MORT', 'Un tir de proximité distinct des affrontements correspond à la fenêtre de 04:19. Le tireur n''a pas été observé directement par la police.', 'P09 — SEPTIÈME MORT', 'Vers 04 h 19, un homme est tué par un tir de près, hors des affrontements. Personne n’a vu le tireur.'),
('030', 'P13 — OPÉRATION AC-17', 'Des autorisations portuaires atypiques et une réaffectation policière relient Ibarra et Varela; la preuve d''un paiement personnel n''est pas acquise.', 'P13 — OPÉRATION AC-17', 'Des documents du port et un changement d’affectation policière relient Ibarra et Varela. Aucun paiement personnel n’est prouvé.'),
('030', 'P17 — LIENS DE CAMPAGNE', 'Des pièces extérieures au registre permettent de rapprocher Córdova, Serrano et le réseau F-09 sans reconstituer artificiellement le document brûlé.', 'P17 — LIENS DE CAMPAGNE', 'Des documents extérieurs relient Córdova, Serrano et F-09. Ils ne recréent pas le registre brûlé.'),
('030', 'P18 — CODES CROISÉS', 'Les références O-06 et AC-17 se recoupent avec des archives indépendantes. Les codes ne valent preuve que rapprochés des actes et personnes.', 'P18 — CODES CROISÉS', 'Les codes O-06 et AC-17 apparaissent aussi dans d’autres archives. Les codes seuls ne prouvent pas qui a agi.'),
('030', 'P21 — GARANTIE DE SILENCE', 'Une note extérieure antérieure à l''assaut décrit REG-118 comme une garantie de silence dans une négociation du gouverneur. Elle ne reproduit aucune ligne du registre.', 'P21 — GARANTIE DE SILENCE', 'Une note antérieure à l’assaut présente REG-118 comme une garantie de silence dans une négociation du gouverneur.'),
('031', 'RESPONSABILITÉS À ÉTABLIR', 'Les pièces réunies sur la mort des six agents ne suffisent pas encore à répartir les responsabilités entre les trois chefs arrêtés.', 'ORDRE DE L’EMBUSCADE', 'Six agents américains ont été tués dans une embuscade. On ignore encore lequel des trois chefs a ordonné l’attaque.'),
('032', 'DÉTENTION PROLONGÉE', 'Des registres montrent que le responsable de la sécurité a validé des prolongations de détention sans ordre écrit.', 'DÉTENTION PROLONGÉE', 'Le responsable de la sécurité a prolongé des détentions sans ordre écrit.'),
('032', 'ORDRE GÉNÉRAL', 'Aucun document ne prescrit explicitement les mauvais traitements.', 'ORDRE GÉNÉRAL', 'Aucun document ne donne explicitement l’ordre de maltraiter les détenus.'),
('032', 'CORRECTION MANUSCRITE', 'Le chef administratif a modifié une liste après avoir été averti d’une détention abusive.', 'CORRECTION MANUSCRITE', 'Le chef administratif a changé une liste après avoir appris qu’une détention était abusive.'),
('032', 'TROIS ÉTAPES', 'Les documents séparent trois étapes : la désignation d’un opposant, l’ordre administratif et son arrestation.', 'TROIS ÉTAPES', 'Les archives séparent trois faits : un opposant désigné, un ordre administratif, puis une arrestation.'),
('033', 'FINANCEMENT', 'Des fonds privés soutiennent une structure de sécurité après révélation d’abus.', 'FINANCEMENT', 'Un groupe de sécurité a reçu des fonds privés après des révélations sur des abus.'),
('033', 'NOMINATION', 'Le membre de la famille occupant le poste ministériel a maintenu une nomination contestée.', 'NOMINATION', 'Le parent de la famille qui est ministre a maintenu une nomination contestée.'),
('033', 'AGENDA PRIVÉ', 'Des rendez-vous montrent que le conseiller familial, sans fonction officielle majeure, était consulté avant plusieurs décisions.', 'AGENDA PRIVÉ', 'Le conseiller familial était consulté avant plusieurs décisions, malgré sa fonction officielle limitée.'),
('033', 'LIEN DE SANG', 'Un proche non impliqué est accusé uniquement en raison de sa parenté.', 'LIEN DE SANG', 'Un proche est accusé seulement à cause de son lien avec la famille.'),
('033', 'PROTECTION', 'Le ministre bloque une enquête administrative sur un chef de service.', 'PROTECTION', 'Le ministre a bloqué une enquête sur un chef de service.'),
('033', 'POUVOIR RÉEL', 'Plusieurs décisions sensibles ont suivi des réunions avec le conseiller familial, malgré son titre officiel limité.', 'POUVOIR RÉEL', 'Plusieurs décisions sensibles ont suivi des réunions avec le conseiller familial, malgré son faible titre officiel.'),
('034', 'CARNET DE SURNOMS', 'Un carnet relie les trois surnoms à des fonctions variables selon les dossiers.', 'CARNET DE SURNOMS', 'Dans les dossiers, les trois surnoms ne désignent pas toujours les mêmes fonctions.'),
('034', 'TRANSFERT', 'Le Notaire valide un transfert après réception d’un avertissement.', 'TRANSFERT', 'Le Notaire a approuvé un transfert après avoir reçu un avertissement.'),
('034', 'INFORMATION BLOQUÉE', 'La Tour reçoit une alerte crédible mais ne la transmet pas avant une opération.', 'INFORMATION BLOQUÉE', 'La Tour a reçu une alerte crédible, mais ne l’a pas transmise avant une opération.'),
('034', 'FAUSSE HIÉRARCHIE', 'Un document interne utilise un surnom prestigieux pour un acteur sans pouvoir décisionnel.', 'FAUSSE HIÉRARCHIE', 'Un document donne un surnom important à quelqu’un qui n’avait pas le pouvoir de décider.'),
('034', 'ACCÈS AU SOMMET', 'L’Héritier apparaît dans plusieurs réunions précédant des décisions majeures.', 'ACCÈS AU SOMMET', 'L’Héritier apparaît dans plusieurs réunions avant des décisions importantes.'),
('034', 'RECOMMANDATION', 'Une note relie directement l’Héritier à la recommandation d’une opération criminelle.', 'RECOMMANDATION', 'Une note indique que l’Héritier a recommandé une opération criminelle.'),
('035', 'REGISTRE IMPOSSIBLE', 'Deux entrées administratives attribuées à M-17 ont été créées après les événements qu’elles sont censées enregistrer.', 'REGISTRE IMPOSSIBLE', 'Deux lignes du dossier M-17 ont été écrites après les événements qu’elles sont censées décrire.'),
('035', 'RENOUVELLEMENT EXCEPTIONNEL', 'L’identité a été renouvelée plusieurs fois sans contrôle biométrique complet, sur dérogation interne.', 'RENOUVELLEMENT EXCEPTIONNEL', 'L’identité M-17 a été renouvelée plusieurs fois sans contrôle biométrique complet.'),
('035', 'ALERTE RETIRÉE', 'Un brouillon d’alerte interne existe, puis disparaît du circuit officiel le lendemain.', 'ALERTE RETIRÉE', 'Une alerte interne a été rédigée, puis retirée du dossier officiel le lendemain.'),
('035', 'CELLULE NACRE', 'Le nom de code NACRE apparaît dans trois dossiers liés à la même identité fantôme.', 'CELLULE NACRE', 'Le nom NACRE figure dans trois dossiers liés à M-17.'),
('035', 'COUPURE DE LIEN', 'Un message interne ordonne de couper tout contact avec M-17 avant que sa mort ne soit connue publiquement.', 'COUPURE DE LIEN', 'Un ordre interne demande de ne plus contacter M-17 avant même l’annonce de sa mort.'),
('036', 'SOURCE NON AUTHENTIFIÉE', 'La première attribution étrangère repose sur un canal qui n’a jamais été authentifié.', 'SOURCE NON AUTHENTIFIÉE', 'La première accusation visant l’étranger repose sur une source qui n’a pas été vérifiée.'),
('036', 'COULOIR VIDE', 'Un couloir logistique secondaire reste sans surveillance pendant onze minutes après 04:17.', 'COULOIR VIDE', 'Un couloir de service est resté sans surveillance pendant onze minutes après 04 h 17.'),
('036', 'VÉHICULE EXTÉRIEUR', 'Une caméra éloignée montre un véhicule quitter le périmètre pendant la diversion.', 'VÉHICULE EXTÉRIEUR', 'Une caméra montre un véhicule quitter le site pendant la diversion.'),
('036', 'CONTENEUR SCELLÉ', 'Le manifeste officiel ne mentionne aucun conteneur correspondant à celui vu sur la caméra.', 'CONTENEUR SCELLÉ', 'Aucun document de transport officiel ne mentionne le conteneur vu sur la caméra.'),
('036', 'FAUX DRAPEAU', 'Plusieurs éléments de communication ont été préparés avant que l’identité des auteurs puisse être établie.', 'MESSAGES PRÉPARÉS TROP TÔT', 'Des messages étaient prêts avant même que les auteurs de l’attaque soient identifiés.'),
('036', 'RELAIS CERBÈRES', 'L’intermédiaire CERBÈRES présent sur le site est relié à une identité déjà utilisée dans le dossier M-17.', 'RELAIS CERBÈRES', 'Un intermédiaire de CERBÈRES est lié à une identité déjà apparue dans le dossier M-17.'),
('037', 'PRÉ-ENTRETIEN', 'La source a vu plusieurs photographies avant le début de l’enregistrement officiel.', 'PRÉ-ENTRETIEN', 'La source avait déjà vu plusieurs photos avant son entretien officiel.'),
('037', 'TRANSCRIPTION NETTOYÉE', 'Une comparaison de fichiers montre qu’une contradiction a disparu de la version finale.', 'TRANSCRIPTION NETTOYÉE', 'Une contradiction présente dans la première transcription a disparu de la version finale.'),
('037', 'ORPHÉE ANTÉRIEUR', 'Une note datée d’avant l’arrestation contient déjà le mot ORPHÉE.', 'ORPHÉE ANTÉRIEUR', 'Une note mentionne ORPHÉE avant même l’arrestation de la source.'),
('037', 'NOM IMPOSSIBLE', 'L’un des noms fournis par la source ne correspond à aucune personne vérifiable.', 'NOM IMPOSSIBLE', 'Un des noms cités par la source ne correspond à personne de vérifiable.'),
('037', 'DÉTAIL INDÉPENDANT', 'Un détail livré pendant l’entretien est confirmé par une source que l’équipe d’interrogation ne possédait pas.', 'DÉTAIL INDÉPENDANT', 'Une autre source confirme un détail que les enquêteurs ignoraient.'),
('037', 'RELAIS SUPÉRIEUR', 'Le recoupement final confirme que la source connaissait bien un relais supérieur de CERBÈRES, sans valider tout son récit.', 'RELAIS SUPÉRIEUR', 'La source connaissait bien un responsable de CERBÈRES, mais cela ne valide pas tout son récit.'),
('038', 'ORDRE DE DISSOLUTION', 'Un ordre officiel exigeait la fermeture d’ORPHÉE plusieurs années plus tôt.', 'ORDRE DE DISSOLUTION', 'Un ordre officiel exigeait la fermeture d’ORPHÉE depuis plusieurs années.'),
('038', 'DÉROGATION HORS INVENTAIRE', 'Une dérogation signée maintient certains moyens sans les faire apparaître dans l’inventaire central.', 'DÉROGATION HORS INVENTAIRE', 'Une autorisation a permis de garder des ressources hors du registre officiel.'),
('038', 'NŒUDS RÉACTIVÉS', 'Plusieurs relais déjà identifiés recommencent à communiquer au même moment pendant la crise de 04:17.', 'NŒUDS RÉACTIVÉS', 'Pendant la crise de 04 h 17, plusieurs contacts du réseau se remettent à communiquer.'),
('038', 'LISTE DÉTRUITE', 'L’opérateur chargé des liaisons de CERBÈRES détruit une liste de contacts après la mort de M-17.', 'LISTE DÉTRUITE', 'L’opérateur de CERBÈRES a détruit une liste de contacts après la mort de M-17.'),
('038', 'OBJECTIF ORPHÉE', 'ORPHÉE est décrit dans une note ancienne comme la protection d’un actif stratégique déplacé hors inventaire.', 'OBJECTIF ORPHÉE', 'Une vieille note affirme qu’ORPHÉE protégeait une ressource stratégique absente des inventaires.'),
('038', 'CONTINUITÉ VOLONTAIRE', 'La coordination a choisi de maintenir le réseau après sa fermeture officielle, avec couverture institutionnelle partielle.', 'CONTINUITÉ VOLONTAIRE', 'Des responsables ont maintenu ORPHÉE après sa fermeture, avec l’aide de certains services officiels.'),
('039', 'CHAÎNE DE VALIDATION', 'Plusieurs décisions sur ORPHÉE exigeaient la validation conjointe de personnes appartenant à CERBÈRES et à l’appareil d’État.', 'CHAÎNE DE VALIDATION', 'Des décisions sur ORPHÉE devaient être approuvées à la fois par CERBÈRES et des responsables de l’État.'),
('039', 'TRANSFERT IRRÉGULIER', 'Le contrôle du site change sans document officiel pendant la crise.', 'TRANSFERT IRRÉGULIER', 'Pendant la crise, le contrôle du site a été transféré sans document officiel.'),
('039', 'TENTATIVE BLOQUÉE', 'Une demande officielle de reprise d’ORPHÉE a été bloquée par le relais politique lié à CERBÈRES.', 'TENTATIVE BLOQUÉE', 'Le relais politique de CERBÈRES a bloqué une demande officielle de reprise d’ORPHÉE.'),
('039', 'OPTION DE CRISE', 'Le coordinateur d’ORPHÉE a préparé une solution politique de dernier recours, sans ordre légal confirmé.', 'OPTION DE CRISE', 'Le coordinateur d’ORPHÉE a préparé une solution politique d’urgence sans autorisation légale connue.'),
('039', 'GARDE DU SITE', 'Aucune pièce ne prouve que le responsable de la sécurité du site connaissait l’objectif complet d’ORPHÉE au moment du transfert.', 'GARDE DU SITE', 'Rien ne prouve que le chef de la sécurité connaissait tout l’objectif d’ORPHÉE lors du transfert.'),
('039', 'RÉSEAU TOUJOURS ACTIF', 'Les archives montrent que des responsables liés à ORPHÉE continuent de coordonner des actions après sa fermeture officielle.', 'RÉSEAU TOUJOURS ACTIF', 'Des responsables ont continué à coordonner des actions autour d’ORPHÉE après sa fermeture.'),
('040', 'RENDEZ-VOUS SECRET', 'L’Oyabun a rencontré le Wakagashira Arakida une semaine avant sa mort sans en informer son propre clan.', 'RENDEZ-VOUS SECRET', 'L’Oyabun a rencontré le Wakagashira Arakida en secret, une semaine avant sa mort.'),
('040', 'DOSSIER PARTIEL', 'Le Wakagashira Kurokawa possède une copie incomplète d’un dossier préparé par l’Oyabun.', 'DOSSIER PARTIEL', 'Le Wakagashira Kurokawa détient une copie incomplète d’un dossier préparé par l’Oyabun.'),
('040', 'VÉHICULE OFFICIEUX', 'Une photographie montre un véhicule utilisé par un service de police près d’un rendez-vous Kurokawa antérieur.', 'VÉHICULE OFFICIEUX', 'Une photo montre une voiture utilisée par la police près d’un ancien rendez-vous Kurokawa.'),
('040', 'DETTE ANCIENNE', 'Le Kobun Kurokawa a bénéficié plusieurs années plus tôt d’une intervention extérieure jamais expliquée au clan.', 'DETTE ANCIENNE', 'Le Kobun Kurokawa avait reçu une aide extérieure dans une ancienne affaire. Le clan ne savait pas de qui.'),
('040', 'PRÉSENCE PROCHE', 'Des données de déplacement placent le Kobun Kurokawa près du lieu du meurtre avant l’alerte officielle.', 'PRÉSENCE PROCHE', 'Le Kobun Kurokawa se trouvait près du lieu du meurtre avant l’alerte officielle.'),
('040', 'RUPTURE PRÉPARÉE', 'Le dossier de l’Oyabun montre qu’il préparait la fin d’une relation ancienne avec un relais institutionnel.', 'RUPTURE PRÉPARÉE', 'L’Oyabun voulait rompre une ancienne relation secrète avec un contact officiel.'),
('041', 'AFFAIRE CLASSÉE', 'Une ancienne procédure visant le Kobun Kurokawa s’est terminée brutalement après une intervention inexpliquée.', 'AFFAIRE CLASSÉE', 'Une enquête visant le Kobun Kurokawa s’est arrêtée après une intervention inexpliquée.'),
('041', 'RAPPEL DE FAVEUR', 'Un message reçu avant le meurtre utilise une formule connue entre le Kobun et son ancien protecteur.', 'RAPPEL DE FAVEUR', 'Avant le meurtre, le Kobun Kurokawa reçoit un message avec une formule connue de son ancien protecteur.'),
('041', 'RELAIS IDENTIFIÉ', 'Le véhicule officieux est relié à un relais précis de la police, sans prouver à lui seul un ordre de meurtre.', 'RELAIS IDENTIFIÉ', 'Une voiture utilisée par la police est reliée à un contact précis. Aucun ordre de meurtre n’est prouvé.'),
('041', 'DETTE COMMERCIALE', 'Les deux Wakagashira ont eux-mêmes maintenu une obligation financière discrète entre clans rivaux.', 'DETTE COMMERCIALE', 'Les deux Wakagashira avaient gardé une dette d’argent secrète entre leurs clans.'),
('041', 'NOTE DE L’OYABUN', 'L’Oyabun considérait la dette du Kobun comme un risque pour l’indépendance du clan.', 'NOTE DE L’OYABUN', 'L’Oyabun pensait que la dette du Kobun mettait l’indépendance de son clan en danger.'),
('041', 'GIRI', 'Un message rappelant une ancienne faveur a été reçu peu avant le meurtre de l’Oyabun. Un relais institutionnel est associé à cet échange.', 'GIRI', 'Le Kobun Kurokawa reçoit un rappel d’une ancienne faveur peu avant le meurtre. Un contact policier y est lié.'),
('042', 'INFORMATION RÉSERVÉE', 'L’horaire donné aux clans provient d’un dossier de police non public.', 'INFORMATION RÉSERVÉE', 'Les clans ont reçu un horaire provenant d’un dossier de police non public.'),
('042', 'ÉCHANGE OFFICIEUX', 'Le Wakagashira Kurokawa a accepté une action en échange d’une information sur le meurtre.', 'ÉCHANGE OFFICIEUX', 'Le Wakagashira Kurokawa a promis d’agir en échange d’une information sur le meurtre.'),
('042', 'COPIE PARTIELLE', 'Le Wakagashira Arakida a fait circuler une partie des documents vers un contact politique.', 'COPIE PARTIELLE', 'Le Wakagashira Arakida a envoyé une partie des documents à un contact politique.'),
('042', 'AVERTISSEMENT', 'Le Kobun Kurokawa a prévenu un relais policier que son clan commençait à comprendre la chaîne.', 'AVERTISSEMENT', 'Le Kobun Kurokawa a prévenu un policier que son clan commençait à comprendre l’affaire.'),
('042', 'ENREGISTREMENT', 'Une conversation montre que le relais demande des résultats sans apparaître dans la procédure.', 'ENREGISTREMENT', 'Un enregistrement montre qu’un policier demande des résultats sans passer par la procédure officielle.'),
('042', 'DEMANDES HORS PROCÉDURE', 'Des demandes adressées aux clans proviennent d’un contact policier, mais aucune procédure officielle ne les autorise.', 'DEMANDES HORS PROCÉDURE', 'Un policier a demandé des actions aux clans sans passer par la procédure officielle.'),
('043', 'ASSURANCE DE COUVERTURE', 'Le Kobun a reçu l’assurance qu’une première piste orienterait l’enquête vers Arakida.', 'ASSURANCE DE COUVERTURE', 'Le Kobun Kurokawa a reçu la promesse que l’enquête viserait d’abord Arakida.'),
('043', 'RIPOSTE SUSPENDUE', 'Le Wakagashira Arakida avait préparé une riposte après le meurtre, puis l’a stoppée avant exécution.', 'RIPOSTE SUSPENDUE', 'Le Wakagashira Arakida avait préparé une riposte après le meurtre, puis l’a arrêtée.'),
('043', 'COPIE EXTERNE', 'Le Kobun Arakida a placé une copie de son enregistrement hors du contrôle des clans et de la police.', 'COPIE EXTERNE', 'Le Kobun Arakida a mis une copie de son enregistrement hors de portée des clans et de la police.'),
('043', 'CHRONOLOGIE DU RELAIS', 'Le relais policier contacte le Kobun avant le meurtre et reçoit une confirmation après.', 'CHRONOLOGIE DU RELAIS', 'Un policier a contacté le Kobun Kurokawa avant le meurtre et a reçu une confirmation après.'),
('043', 'COOPÉRATION PRÉPARÉE', 'Des éléments montrent que la cellule de coopération police-clans était prête avant l’annonce publique du meurtre.', 'COOPÉRATION PRÉPARÉE', 'La police avait préparé sa coopération avec les clans avant l’annonce officielle de la mort.'),
('043', 'UNE CHRONOLOGIE TROUBLANTE', 'Les horaires relient un rappel de faveur, un contact policier et une version préparée de l’enquête. Les rôles exacts restent contestés.', 'CONTACTS AVANT LE MEURTRE', 'Des contacts policiers ont eu lieu avant le meurtre. Une version des faits était prête très vite après.'),
('044', 'VOLONTÉ DE RUPTURE', 'Le dossier complet confirme que l’Oyabun préparait la fin de la relation clandestine avec le relais policier.', 'VOLONTÉ DE RUPTURE', 'L’Oyabun voulait mettre fin à ses contacts secrets avec un policier.'),
('044', 'DERNIER MESSAGE', 'Le Kobun Kurokawa a conservé un message du relais reçu avant le meurtre qui rappelle explicitement l’ancienne faveur.', 'DERNIER MESSAGE', 'Avant le meurtre, le Kobun Kurokawa reçoit un message lui rappelant une ancienne faveur d’un policier.'),
('044', 'VERSION PUBLIQUE', 'Le Wakagashira Kurokawa a préparé une version qui isole le Kobun et minimise le rôle policier.', 'VERSION PUBLIQUE', 'Le Wakagashira Kurokawa a préparé un récit qui accuse le Kobun et minimise le rôle de la police.'),
('044', 'COPIE HORS CONTRÔLE', 'La copie extérieure de l’enregistrement ne peut plus être garantie comme récupérable ou supprimable.', 'COPIE HORS CONTRÔLE', 'Une copie de l’enregistrement a échappé aux clans et à la police. On ignore si elle peut être récupérée.'),
('044', 'PRÉPARATION POLICIÈRE', 'La cellule de coopération était opérationnelle avant que la mort ne soit annoncée au public.', 'PRÉPARATION POLICIÈRE', 'La police avait préparé sa coopération avec les clans avant l’annonce de la mort de l’Oyabun.'),
('044', 'TROIS TRACES À RECOUPER', 'Avant le meurtre, un message rappelle une dette ancienne. Après, une version incriminant Arakida est préparée. Des contacts policiers précèdent l’annonce publique.', 'APPEL AVANT LE MEURTRE', 'Avant le meurtre, un policier contacte le Kobun Kurokawa. Après, une version accusant Arakida est préparée.'),
('001', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle l’ami auquel il réclame sa dette. Une silhouette compatible avec cet ami quitte le palier à 02 h 32 ; un visiteur encapuchonné entre dans l’hôtel à 02 h 48. Aucune caméra ne filme l’intérieur de 222.', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle un ami qui lui doit de l’argent. Cet ami semble partir à 02 h 32. Un autre homme arrive à 02 h 48.'),
('001', 'DETTE ET ENREGISTREMENT', 'Des messages prouvent que l’ancien ami doit de l’argent à Maël. Une captation enregistrée après 02 h 55 contient l’ordre d’effacer quelque chose, puis des bruits de lutte. Les voix ne sont pas identifiables avec certitude.', 'DETTE ET ENREGISTREMENT', 'Des messages confirment la dette de l’ami. Après 02 h 55, un enregistrement capte un ordre d’effacement et une lutte. Les voix restent incertaines.'),
('001', 'DEUX ALTERCATIONS, UNE LAME', 'Le désordre correspond à deux séquences distinctes : la première avant 02 h 32, la seconde après 02 h 55. Un Opinel ensanglanté et essuyé est retrouvé dans une benne de service. Ces constatations ne prouvent pas qui le portait au moment du coup.', 'DEUX ALTERCATIONS, UNE LAME', 'Deux altercations ont eu lieu. Un couteau ensanglanté est retrouvé dans une benne, mais on ignore qui l’a utilisé.'),
('001', 'LA DISPUTE ET LE VISITEUR', 'Maël appelle son ancien ami à 02 h 11. Une silhouette compatible avec lui quitte l’étage à 02 h 32, avant l’entrée d’un visiteur encapuchonné à 02 h 48. Des bruits de dispute précèdent le départ et un choc retentit vers 03 h 05.', 'LA DISPUTE ET LE VISITEUR', 'Maël se dispute avec son ami avant 02 h 32. Un visiteur arrive à 02 h 48. Un choc est entendu à 03 h 05.'),
('001', 'UNE BLESSURE PLUS ANCIENNE', 'Les traces de saignement et l’examen de la plaie sont compatibles avec une blessure infligée au cours de la première dispute. Maël peut encore parler quelque temps après avoir été blessé. L’expertise ne fournit pas d’heure exacte.', 'UNE BLESSURE PLUS ANCIENNE', 'La blessure de Maël pourrait venir de la première dispute. Il a pu parler ensuite. L’heure exacte reste inconnue.'),
('001', 'LE DERNIER CHOC N’ÉTAIT PAS UN COUP', 'Le choc de 03:05 correspond aux traces d''un meuble renversé. La blessure par lame précède la seconde visite. L''Opinel ne fournit aucune preuve de manipulation par le second visiteur ; celui-ci n''a pas alerté les secours.', 'BRUIT DU MEUBLE', 'Le bruit de 03 h 05 vient d’un meuble. Maël était déjà blessé avant le second visiteur, qui n’a pas appelé les secours.'),
('001', 'DEUX DISPUTES DANS LA MÊME NUIT', 'Maël appelle son ancien ami à 02 h 11. Celui-ci semble quitter le palier à 02 h 32, tandis qu’un visiteur encapuchonné entre à 02 h 48. Une agitation beaucoup plus forte retentit vers 03 h 05 ; personne ne voit ce qui se produit dans 222.', 'DEUX DISPUTES DANS LA MÊME NUIT', 'L’ami de Maël part vers 02 h 32. Un visiteur arrive à 02 h 48. Vers 03 h 05, une agitation éclate dans la chambre.'),
('001', 'UNE TROISIÈME PRÉSENCE POSSIBLE', 'Une trace sur la poignée intérieure est compatible avec le passage d’un troisième intervenant lors de la lutte tardive. Une marque de préhension est observée sur la manche de Maël. Ces indices ne désignent pas avec certitude la personne entrée dans 222.', 'UNE TROISIÈME PRÉSENCE POSSIBLE', 'Une trace sur la poignée et une marque sur la manche de Maël suggèrent une troisième présence. Rien ne l’identifie.'),
('001', 'LA TRAJECTOIRE NE DIT PAS L’INTENTION', 'La plaie est compatible avec un mouvement brusque du poignet tenant le couteau pendant la lutte. Ce mécanisme peut être accidentel, mais seule la confrontation des versions permet d’en examiner la cause. Provoquer la blessure ne démontre pas l’intention de tuer.', 'LA TRAJECTOIRE NE DIT PAS L’INTENTION', 'La blessure a pu venir d’un geste brusque pendant la lutte. Elle ne prouve pas une volonté de tuer.'),
('002', 'LA CONFIDENCE PUBLIÉE', 'À 20 h 51, une nouvelle publication reprend des propos que Léon avait confiés en privé. Son auteur est identifié. Le nombre de partages ne permet pas de mesurer son effet sur Léon.', 'LA CONFIDENCE PUBLIÉE', 'À 20 h 51, quelqu’un publie une confidence privée de Léon. L’auteur est connu, pas l’effet exact sur Léon.'),
('002', 'CE QUI S’EST RÉPÉTÉ', 'Les archives montrent que la publication de 20 h 51 n’était pas la première. Les humiliations sont réparties sur plusieurs semaines. Les messages hostiles de l''autre proche appartiennent à un conflit distinct.', 'CE QUI S’EST RÉPÉTÉ', 'Les humiliations contre Léon duraient depuis des semaines. Les messages d’un autre proche relèvent d’un conflit distinct.'),
('002', 'QUATRE CONDUITES, PAS UNE CAUSE UNIQUE', 'Les heures établissent des actes distincts : humiliation répétée, messages violents, pleurs entendus sans intervention et dernier départ du meilleur ami. Ces faits sont documentés ; aucun ne permet d''attribuer à lui seul la mort de Léon.', 'QUATRE CONDUITES, PAS UNE CAUSE UNIQUE', 'Léon a subi des humiliations, des messages violents et des refus d’aide. Aucun fait ne suffit seul à expliquer sa mort.'),
('002', 'LE MESSAGE D’ALERTE', 'À 22 h 16, Léon écrit à son meilleur ami qu''il traverse une crise et lui demande de contacter une aide extérieure. La réception du message est confirmée, sans que l''on sache encore comment il a réagi.', 'LE MESSAGE D’ALERTE', 'À 22 h 16, Léon demande à son meilleur ami d’appeler de l’aide. Le message a été reçu.'),
('002', 'L’AIDE RESTÉE SUR LE PAPIER', 'À 22 h 23, le meilleur ami rédige une note pour contacter une aide extérieure. Aucun appel correspondant n''est enregistré ensuite. Les pleurs entendus par le voisin ne prouvent pas qu''il connaissait la teneur de l''alerte.', 'L’AIDE RESTÉE SUR LE PAPIER', 'À 22 h 23, son meilleur ami écrit qu’il faut appeler de l’aide. Aucun appel correspondant n’apparaît ensuite.'),
('002', 'LE DÉLAI ET LES INFORMATIONS', 'L''alerte a été reçue. Le besoin d''aide a été compris : la note le confirme. L''appel n''a pas été passé. Les humiliations antérieures et les messages cruels restent des faits séparés. Rien ne permet d''affirmer qu''une aide aurait certainement empêché le décès.', 'LE DÉLAI ET LES INFORMATIONS', 'Le meilleur ami a compris la demande d’aide, mais n’a pas appelé. On ignore si les secours auraient évité la mort.'),
('002', 'UNE CONFIDENCE DIFFUSÉE', 'Léon découvre qu''une confidence privée circule. Plus tard, un conflit avec son ancien colocataire se termine par des paroles dures. Ces épisodes ne prouvent pas une intention collective.', 'UNE CONFIDENCE DIFFUSÉE', 'Une confidence de Léon a été diffusée. Il se dispute ensuite avec son ancien colocataire. Rien ne prouve une action commune.'),
('002', 'UNE EXCUSE SANS ACCUSÉ DE LECTURE', 'À 21:58, L’ancien ami envoie des excuses sans confirmation de lecture. Le voisin entend ensuite des pleurs et lit à 22:12 une demande de prévenir un ami, sans la transmettre.', 'UNE EXCUSE SANS ACCUSÉ DE LECTURE', 'À 21 h 58, un ancien ami s’excuse sans preuve de lecture. À 22 h 12, le voisin lit un message demandant de prévenir un proche, mais ne le transmet pas.'),
('002', 'PERSONNE N’AVAIT LA MÊME HISTOIRE', 'Le voisin a lu une demande personnelle de prévenir un proche et n''a rien transmis. Le meilleur ami, ignorant ce message, est venu de sa propre initiative puis est reparti. Aucune cause unique du décès ne peut être déduite.', 'PERSONNE N’AVAIT LA MÊME HISTOIRE', 'Le voisin ne transmet pas la demande de Léon. Le meilleur ami, qui l’ignorait, vient puis repart.'),
('003', 'LE DOSSIER ORIGINAL', 'Le dossier scientifique signalait le danger avant les décisions. La question est désormais de savoir qui l''avait réellement lu.', 'LE DOSSIER ORIGINAL', 'Un dossier scientifique signalait un danger avant les décisions. On ignore encore qui l’avait lu.'),
('003', 'DEUX COPIES DIFFÉRENTES', 'L''avertissement figure dans le dossier d''Helios, mais pas dans la copie reçue par le gouvernement avant le départ.', 'DEUX COPIES DIFFÉRENTES', 'L’avertissement figure dans les archives d’Helios, mais pas dans la copie envoyée au gouvernement.'),
('003', 'TROIS DÉCISIONS DISTINCTES', 'S1 a maintenu les opérations, S2 a autorisé le transport malgré l''avertissement et S3 a supprimé celui-ci de la copie gouvernementale.', 'TROIS DÉCISIONS DISTINCTES', 'Les documents séparent trois décisions : poursuivre, autoriser le transport et retirer l’avertissement.'),
('003', 'Deux documents incompatibles', 'Le service des validations reçoit à 08 h 24 deux constats contradictoires. Une décision de conformité ne peut pas les réconcilier à elle seule.', 'Deux documents incompatibles', 'À 08 h 24, le service des validations reçoit deux rapports qui se contredisent.'),
('003', 'Le statut « conforme »', 'À 08 h 47, le registre est clos sans justification de la contradiction. Le directeur consulte ensuite cette validation, et non les annotations internes.', 'Le statut « conforme »', 'À 08 h 47, le registre est déclaré conforme sans résoudre la contradiction. Le directeur ne voit que cette validation.'),
('003', 'La décision a précédé l''explication', 'Le service a marqué le dossier conforme avant d''avoir expliqué l''écart. Le directeur s''est fondé sur cette validation et le contrôleur n''a pas obtenu la correction demandée. Rien ne prouve une fraude intentionnelle.', 'La décision a précédé l''explication', 'Le dossier a été déclaré conforme avant la correction des contradictions. Rien ne prouve une fraude volontaire.'),
('003', 'LE DOSSIER ÉTAIT SIGNÉ', 'Le dossier signé par S2 permet la poursuite. L''enquête doit établir les informations connues avant cette signature.', 'LE DOSSIER ÉTAIT SIGNÉ', 'Un dossier signé autorise la poursuite. On ignore encore ce que son signataire savait.'),
('003', 'S2 AVAIT LU LE DANGER', 'S2 a lu l''avertissement avant de signer. S1 n''a reçu que le dossier qui affirmait que tout était en ordre.', 'AVERTISSEMENT CONNU', 'Le signataire connaissait l’avertissement. Le directeur n’avait reçu qu’une copie disant que tout allait bien.'),
('003', 'LE MENSONGE, PUIS LE SILENCE', 'S2 a signé sciemment un dossier faux. S3 a caché ensuite le danger découvert avant le départ. Les deux décisions sont distinctes.', 'LE MENSONGE, PUIS LE SILENCE', 'Un dossier faux a été signé. L’avertissement a été caché ensuite, par une autre personne.'),
('003', 'UN ACCORD ANNONCÉ', 'Le dossier affirme que l''équipe destinataire avait accepté le transport. L''enquête cherche à retrouver cet accord.', 'UN ACCORD ANNONCÉ', 'Le dossier affirme que l’équipe destinataire avait accepté le transport. Cet accord reste introuvable.'),
('003', 'LE TRANSPORT POUVAIT ENCORE ÊTRE ARRÊTÉ', 'L''équipe destinataire affirme n''avoir rien accepté. Un avertissement reçu avant le départ devait entraîner son arrêt.', 'LE TRANSPORT POUVAIT ENCORE ÊTRE ARRÊTÉ', 'L’équipe destinataire dit n’avoir jamais accepté le transport. Un avertissement aurait dû l’arrêter.'),
('003', 'S3 A CACHÉ LE DERNIER AVERTISSEMENT', 'S1 a menacé S2, S2 a inventé l''accord et S3 a retiré l''avertissement qui aurait permis à la sécurité d''arrêter le transport.', 'AVERTISSEMENT RETIRÉ', 'Des échanges montrent une menace, un faux accord et un avertissement retiré. Ces actes ont précédé le transport.'),
('004', 'APPEL REÇU', 'Le journal confirme un appel de Sofia à l''ex-partenaire avant tous les autres échanges. Son contenu n''est pas publié à ce stade.', 'APPEL À L’EX-PARTENAIRE', 'Le téléphone de Sofia confirme qu’elle a appelé son ex-partenaire avant les autres échanges. On ignore ce qu’ils se sont dit.'),
('004', 'TROIS NIVEAUX D''INFORMATION', 'Le message reçu par l''ami est moins explicite que le témoignage sur le premier appel. Aucun échange ne confirme qu''un relais était organisé.', 'MESSAGES DIFFÉRENTS', 'Sofia envoie à son ami un message moins alarmant que son premier appel. Rien ne montre qu’un proche devait prévenir l’autre.'),
('004', 'LA QUESTION NON ENVOYÉE', 'Une question non expédiée apparaît dans le téléphone de l''ami. La trace du passage dans la rue ne comporte aucun avis transmis au proche. L''enquête doit établir ce que chacun pouvait savoir, sans inférer une issue médicale certaine.', 'QUESTION NON ENVOYÉE', 'L’ami de Sofia a rédigé une question sans l’envoyer. Aucun message ne montre que le proche passé dans la rue avait été prévenu.'),
('004', 'DEUX ALERTES DISTINCTES', 'Deux messages adressés à des destinataires différents arrivent après la rupture du premier suspect. Le contenu exact de leur conversation n''est pas encore connu.', 'DEUX MESSAGES DIFFÉRENTS', 'Après une dispute avec son ex-partenaire, Sofia envoie deux messages différents : un à son ami proche, l’autre au proche du quartier.'),
('004', 'L''APPEL ENTRE PROCHES', 'Le journal prouve une conversation entre les deux destinataires des alertes. Aucune trace de contact avec Sofia ou un service d''aide ne suit cet échange.', 'APPEL ENTRE LES PROCHES', 'L’ami proche de Sofia et le proche du quartier se sont appelés après ses messages. Aucun appel aux secours n’apparaît ensuite.'),
('004', 'UN RELAIS SANS ACCORD', 'La comparaison des messages et des témoignages ne permet d''identifier aucune attribution explicite de la prise en charge. Les deux proches connaissaient l''inquiétude de l''autre. L''enquête doit déterminer la part de chacun.', 'PERSONNE NE SE CHARGE DES SECOURS', 'Les messages ne disent pas si l’ami proche de Sofia ou le proche du quartier devait venir l’aider ou appeler les secours.'),
('004', 'LE PREMIER TÉMOIN', 'Un proche est aperçu dans la rue et nie d''abord sa présence. La seule présence ne permet pas encore d''établir ce qu''il savait.', 'PRÉSENCE DANS LA RUE', 'Le proche de Sofia qui habite le quartier est vu dans la rue. Il avait d’abord nié être passé. On ignore ce qu’il savait.'),
('004', 'UN DÉCALAGE ENTRE LES HEURES', 'Les journaux montrent que l''appel à l''ex-partenaire et le message à l''ami précèdent le passage rapporté. Aucun relais au troisième proche n''est documenté.', 'MESSAGES AVANT LE PASSAGE', 'Sofia a appelé son ex-partenaire et écrit à son ami avant le passage du proche du quartier. Rien ne montre qu’il avait été prévenu.'),
('004', 'LA RUMEUR N''ÉTAIT PAS UNE ALERTE', 'L''horodatage du passage est authentifié mais postérieur aux messages. La rumeur inverse cet ordre. Le silence du troisième proche sur sa présence n''efface pas les choix antérieurs des deux premiers.', 'LA CAMÉRA CONTREDIT LA RUMEUR', 'La caméra situe le passage du proche du quartier après les messages. Une rumeur disait l’inverse. Les deux autres proches avaient reçu leurs alertes avant.'),
('005', 'L''agence savait', 'Des documents montrent que Keller avait été alerté de la détresse de Mara. Sa mort a laissé des proches en colère.', 'L''agence savait', 'Des documents montrent que Keller connaissait la détresse de Mara. Sa mort a laissé ses proches en colère.'),
('005', 'Trois déplacements', 'Une vidéo et un badge situent deux suspects ailleurs. Une troisième visite commence quelques minutes avant la mort.', 'Trois déplacements', 'Une caméra et un badge placent deux suspects ailleurs. Une troisième visite commence peu avant la mort de Keller.'),
('005', 'La copie laissée au sol', 'Le masque a servi pendant la confrontation puis a été posé près du corps, avec des portraits abîmés. La scène ne prouve pas le retour du tueur original.', 'La copie laissée au sol', 'Le masque est utilisé pendant la dispute, puis posé près du corps. Cela ne prouve pas le retour de l’ancien tueur.'),
('005', 'Le sourire du gala', 'Keller affiche publiquement le respect des mannequins, mais une dispute éclate juste avant l''ouverture de la soirée.', 'Le sourire du gala', 'Au gala, Keller se présente comme respectueux. Une dispute éclate pourtant avant le début de la soirée.'),
('005', 'Le salon privé', 'Une ouverture du salon est enregistrée à 21 h 09. Le discours sur scène se poursuit pendant la mort.', 'Le salon privé', 'Le salon privé est ouvert à 21 h 09 pendant que le discours continue ailleurs.'),
('005', 'Un masque venu de l''extérieur', 'Le masque a été apporté et porté par le meurtrier, puis laissé dans le salon. Le dossier de Mara n''est pris qu''après sa mort.', 'Un masque venu de l''extérieur', 'Le meurtrier a apporté et porté le masque. Le dossier de Mara a été pris après la mort de Keller.'),
('005', 'Une visite masquée', 'Une personne masquée est signalée avant la mort de Keller. Cela ne suffit pas à identifier l''auteur des coups.', 'Une visite masquée', 'Une personne masquée est vue avant la mort de Keller. Rien ne prouve que c’est elle qui l’a frappé.'),
('005', 'Deux portes', 'La sortie de l''ouest et l''entrée de l''est se produisent vers 20 h 57, dans des couloirs séparés.', 'Deux portes', 'Une personne sort à l’ouest et une autre entre à l’est vers 20 h 57.'),
('005', 'Trois actes', 'Les heures distinguent une menace, une lutte mortelle et un déplacement du masque. Les documents manquants ajoutent une dernière piste.', 'Trois actes', 'Les heures montrent une menace, une lutte mortelle puis le déplacement du masque. Des documents manquent encore.'),
('006', 'UNE SORTIE ORDINAIRE', 'Les quatre amis ont été photographiés au belvédère et leur appel aux secours depuis le chalet a été enregistré.', 'UNE SORTIE ORDINAIRE', 'Une photo montre les quatre amis au belvédère. Leur appel aux secours depuis le chalet est enregistré.'),
('006', 'LE DÉFI CACHÉ', 'La vidéo montre une provocation ciblée contre Noé. Mathis était intervenu avant la chute.', 'LE DÉFI CACHÉ', 'Une vidéo montre que Noé a été provoqué. Mathis est intervenu avant la chute.'),
('006', 'LES DERNIÈRES SECONDES', 'La confrontation des pièces et des positions permet de distinguer le dernier geste du mensonge partagé.', 'DERNIER GESTE CONTESTÉ', 'Les traces du dernier geste et la version donnée par les trois amis ne racontent pas la même chose.'),
('007', 'UN TESTAMENT AVANT LA MORT', 'Le testament porte une signature authentique obtenue sous pression. Une dette privée constitue un autre mobile, sans que ces documents situent quiconque pendant la chute.', 'UN TESTAMENT AVANT LA MORT', 'Le testament est authentique mais signé sous pression. Une dette existe aussi. Ces pièces ne situent personne lors de la chute.'),
('007', 'LA PIÈCE RETIRÉE', 'Une lettre de 2013 sur les comptes d''une ancienne vente a disparu du dossier familial. Un rendez-vous privé autour de cette pièce a été fixé après les départs des deux autres proches.', 'LA PIÈCE RETIRÉE', 'Une lettre de 2013 sur une ancienne vente a disparu. Un rendez-vous secret était prévu après le départ des autres proches.'),
('007', 'DEUX ENTRETIENS, UNE SEULE CHUTE', 'La lettre a été déchirée à proximité du seuil de l''escalier ; des traces d''encre et des horaires situent un contact possible pendant la dispute. La scène ne révèle pas à elle seule qui a fait perdre l''équilibre au défunt, ni avec quelle intention.', 'DEUX ENTRETIENS, UNE SEULE CHUTE', 'Une lettre déchirée est trouvée près de l’escalier. Les traces ne prouvent pas qui a fait tomber la victime.'),
('007', 'L''ULTIMATUM PRÉCÈDE LA LUTTE', 'La signature authentique a été obtenue sous pression. Les relevés de sortie situent le bénéficiaire ailleurs pendant qu''un document de dette devient l''objet d''un rendez-vous.', 'L''ULTIMATUM PRÉCÈDE LA LUTTE', 'La signature est vraie, mais obtenue sous pression. Le bénéficiaire était ailleurs lors du rendez-vous sur la dette.'),
('007', 'UNE PIÈCE CHANGE DE PLACE', 'Une rencontre privée concerne les justificatifs d''une dette, pas une nouvelle modification du testament. La chemise financière est ensuite photographiée dans la pièce où se trouve le défunt.', 'UNE PIÈCE CHANGE DE PLACE', 'Une rencontre portait sur une dette, pas sur le testament. Les documents ont ensuite été photographiés près du défunt.'),
('007', 'LE RENDEZ-VOUS SUR LA DETTE', 'Le dossier apparaît sur une photographie postérieure à la chute, avant de disparaître de l''inventaire. Des traces sur les vêtements et les horaires permettent de distinguer le contact au palier de la dissimulation ultérieure, sans déduire l''intention du seul retrait.', 'LE RENDEZ-VOUS SUR LA DETTE', 'Le dossier financier apparaît sur une photo après la chute, puis disparaît. Cela ne prouve pas une intention de tuer.'),
('007', 'LA COPIE QUI DÉRANGE', 'Une copie datée révèle un lien de filiation absent du projet de testament. La provenance du duplicata est identifiable, mais sa valeur successorale reste à apprécier. Cette découverte donne un motif à plusieurs proches ; elle ne permet d’imputer ni la lutte ni la chute.', 'LA COPIE QUI DÉRANGE', 'Une copie révèle un lien de parenté absent du testament. Plusieurs proches ont un intérêt, sans preuve sur la chute.'),
('007', 'DEUX RENDEZ-VOUS DISTINCTS', 'Le registre de sortie place le bénéficiaire hors de la propriété dès 17 h 06. À 17 h 35, une demande de rencontre concerne l’original de l’attestation et non le projet de testament. La liste d’accès établit une présence tardive, pas encore le geste à l’origine du décès.', 'DEUX RENDEZ-VOUS DISTINCTS', 'Le bénéficiaire est parti à 17 h 06. À 17 h 35, une rencontre est demandée pour une attestation, pas pour le testament.'),
('007', 'L’ENVELOPPE ET LA CHUTE', 'À l''issue du dernier entretien, l''enveloppe de l''attestation est abîmée. Des traces sur le poignet du défunt et une manche déchirée appellent une comparaison, mais aucune trace isolée ne montre comment l''équilibre a été perdu. La pression financière et le mensonge sur la filiation restent des questions distinctes.', 'L’ENVELOPPE ET LA CHUTE', 'Une enveloppe abîmée et des marques sur les vêtements montrent un contact, sans prouver comment la victime est tombée.'),
('008', 'LE REGISTRE NE MENT PAS SEUL', 'Le registre original de la salle des archives fixe un retrait autorisé du dossier D-14 à 18 h 12. Le premier témoin a déclaré un contrôle continu jusqu’à 18 h 24, alors que son écriture a été ajoutée après l’audience préparatoire. Le décalage établit une version inexacte, pas l’auteur d’un détournement.', 'LE REGISTRE NE MENT PAS SEUL', 'D-14 est sorti à 18 h 12. Un témoin dit pourtant avoir surveillé la salle jusqu’à 18 h 24.'),
('008', 'UNE DÉPOSITION PRÉPARÉE', 'Un message horodaté, conservé par le système de préparation des dépositions, demande de ne pas évoquer un intervalle sans contrôle. L''authenticité de l''échange est documentée; il faut encore relier son origine, son destinataire et son contexte avant d''imputer une influence précise. Le troisième témoin ne figure pas parmi les destinataires.', 'UNE DÉPOSITION PRÉPARÉE', 'Un message demandait de taire un trou de surveillance. Le troisième témoin ne l’a pas reçu.'),
('008', 'UN MENSONGE, UN FAIT VRAI', 'Un enregistrement de la porte et le registre initial situent la sortie de D-14 à 18 h 12. Les pièces ne prouvent aucune altération. Le troisième témoin a faussé son heure d''arrivée pour une raison personnelle; le premier a masqué une négligence et le deuxième a fait pression sur une déposition. Il reste à qualifier séparément ces comportements.', 'UN MENSONGE, UN FAIT VRAI', 'D-14 est sorti à 18 h 12 sans trace d’altération. Les témoins ont menti sur des faits différents.'),
('008', 'LE SCELLÉ SANS GARDE', 'La feuille de prise en charge du dossier D-14 prévoit une garde continue. Entre 18 h 05 et 18 h 18, aucune signature de relais ni surveillance n’est attestée. Le premier témoin affirme pourtant avoir surveillé la pièce durant tout ce créneau.', 'LE SCELLÉ SANS GARDE', 'D-14 n’a pas été surveillé entre 18 h 05 et 18 h 18. Un témoin affirme pourtant le contraire.'),
('008', 'CORRIGÉ APRÈS L’INCIDENT', 'Une ligne du registre présente une surveillance continue, mais le système situe sa saisie réelle à 18 h 41, après l''intervalle de 18 h 05 à 18 h 18. Un échange préparatoire évoque aussi le silence à garder sur ce créneau. Les comptes de saisie et les destinataires doivent être recoupés pour distinguer l''auteur de la défaillance et celui qui a cherché à la cacher lors de l''audition.', 'CORRIGÉ APRÈS L’INCIDENT', 'Une ligne de surveillance continue a été ajoutée à 18 h 41, après le créneau sans garde.'),
('008', 'LA FAILLE, PAS LA ROMANCE', 'La pièce D-14 n''a pas disparu et le contrôle ne révèle pas d''altération identifiable. Pourtant, entre 18 h 05 et 18 h 18, aucune garde valide n''était assurée. La caméra situe le troisième témoin au vestibule pendant l''intervalle; l''absence de surveillance et les consignes de silence doivent être évaluées séparément.', 'DOSSIER INTACT, GARDE ABSENTE', 'D-14 est intact, mais personne ne le surveillait entre 18 h 05 et 18 h 18. Un témoin était au vestibule.'),
('008', 'UN DÉTAIL IMPOSSIBLE À DEVINER', 'Le troisième témoin décrit la pliure et la marque d’inventaire au dos de D-14, détails absents de la version remise aux témoins. Il affirme pourtant n’avoir jamais manipulé ni revu cette pièce. Cette connaissance exige une explication ; elle ne démontre pas encore le déplacement.', 'UN DÉTAIL IMPOSSIBLE À DEVINER', 'Un témoin décrit une marque cachée au dos de D-14, mais affirme ne jamais avoir revu cette pièce.'),
('008', 'LE SECOND PASSAGE', 'Un badge temporaire apparaît dans les journaux entre 18 h 12 et 18 h 21, après une première visite privée à 17 h 40. Cette autorisation donnait accès au couloir, pas à l''ouverture de D-14. Le second passage doit être rapproché des inventaires et des témoignages; les journaux ne montrent pas le geste matériel ni ses raisons.', 'LE SECOND PASSAGE', 'Un badge temporaire passe entre 18 h 12 et 18 h 21. Il permet l’accès au couloir, pas au dossier D-14.'),
('008', 'LE DOCUMENT A CHANGÉ DE PLACE', 'Deux inventaires établissent que D-14 a changé de casier et que sa bande de scellement a été déchirée. L''accès non expliqué de 18 h 12, les détails du verso connus d''un témoin et les fibres du rabat donnent des pistes convergentes. La confrontation finale doit distinguer celui qui a effectivement touché la pièce de ceux qui ont seulement menti sur d''autres faits.', 'LE DOCUMENT A CHANGÉ DE PLACE', 'D-14 a changé de casier et son scellé est déchiré. Les traces ne disent pas qui l’a déplacé.'),
('009', 'LE REFUS N''EST PAS UNE HÉSITATION', 'À 09 h 14, le Sujet 17 indique sans ambiguïté qu''il retire son consentement et demande la fin du protocole. L''enregistrement horodaté et un reçu de transcription authentifié concordent. Un entretien ultérieur n''a pas effacé ce retrait.', 'LE REFUS N''EST PAS UNE HÉSITATION', 'À 09 h 14, le Sujet 17 retire clairement son accord. Son refus est enregistré.'),
('009', 'RÉCEPTION, VALIDATION, EXÉCUTION', 'L’alerte transmise à 09 h 19 est reçue dans le circuit institutionnel à 09 h 22. Une instruction concernant la continuation d’ORPHÉE circule ensuite. Les accusés de réception, les habilitations et les actes cliniques ne répondent pas à la même question : qui a reçu, qui a validé et qui a exécuté ?', 'RÉCEPTION, VALIDATION, EXÉCUTION', 'Une alerte part à 09 h 19 et est reçue à 09 h 22. Une consigne de continuer circule ensuite.'),
('009', 'UNE MÉMOIRE PERDUE N''EFFACE PAS UNE CONSIGNE', 'Le Sujet 17 manifeste une détresse à 09 h 40, et les exercices cessent à 09 h 42. Le médecin tombe à 09 h 47 en se dirigeant vers le poste de secours. Les évaluations ultérieures sont compatibles avec une atteinte authentique de mémoire récente, mais les journaux antérieurs confirment qu''il avait reçu une consigne institutionnelle de poursuite et exécuté une étape sans nouveau consentement. Il reste à distinguer celui qui a ordonné et celui qui a appliqué.', 'HORAIRES AVANT LA CHUTE', 'Après une détresse à 09 h 40, les exercices cessent à 09 h 42. Le médecin tombe à 09 h 47. Les ordres sont antérieurs.'),
('009', 'LE RETRAIT PRÉCÈDE LA DÉCISION', 'Le Sujet 17 retire explicitement son consentement à 09 h 14. L''enregistrement original et le tableau des actes situent la poursuite du protocole après ce retrait. L''existence d''un formulaire signé plusieurs jours auparavant ne constitue pas un accord nouveau.', 'LE RETRAIT PRÉCÈDE LA DÉCISION', 'Le Sujet 17 retire son accord à 09 h 14. L’expérience continue malgré son refus.'),
('009', 'UN AVIS D’ARRÊT, DES ACTES MAINTENUS', 'À 09 h 21, la direction adresse une recommandation écrite de suspension. Pourtant, une nouvelle étape est consignée à 09 h 34. Le rapprochement des registres doit encore établir qui a effectivement autorisé la poursuite et si l’avis a été respecté.', 'UN AVIS D’ARRÊT, DES ACTES MAINTENUS', 'La direction demande l’arrêt à 09 h 21. Une nouvelle étape de l’expérience a pourtant lieu à 09 h 34.'),
('009', 'L''AMNÉSIE COMMENCE APRÈS LA SIGNATURE', 'Une alerte de détresse est consignée à 09 h 40, les exercices cessent à 09 h 42 et le médecin chute à 09 h 47. Des observations répétées étayent ensuite un trouble mnésique réel. Mais le registre signé par le médecin à 09 h 28 reste antérieur à sa chute, tandis que la direction avait recommandé une suspension à 09 h 21. Le défaut de suivi ne doit pas être confondu avec l''auteur de la décision.', 'SIGNATURE AVANT LA CHUTE', 'Le médecin signe à 09 h 28, puis tombe à 09 h 47 et perd réellement la mémoire. La direction avait demandé l’arrêt.'),
('009', 'LE PREMIER COMPTE RENDU DISAIT NON', 'À 09 h 14, le Sujet 17 retire clairement son accord. La première note de l''équipe, mise sous empreinte numérique, reprend les termes du retrait. Le médecin demande alors une interruption documentée du protocole.', 'LE PREMIER COMPTE RENDU DISAIT NON', 'À 09 h 14, le Sujet 17 retire son accord. Le médecin demande d’arrêter l’expérience.'),
('009', 'DEUX VERSIONS DU MÊME REFUS', 'La note originale consigne un retrait explicite. À 09 h 25, une version ultérieure remplace ce passage par une hésitation, alors que le programme ne s’arrête pas aussitôt. Le journal conserve les deux textes; le circuit de validation doit permettre d’attribuer la correction.', 'DEUX VERSIONS DU MÊME REFUS', 'La première note dit que le Sujet 17 refuse. À 09 h 25, une autre version parle seulement d’hésitation.'),
('009', 'LA COPIE ET LA CHUTE', 'Les empreintes des notes antérieure et postérieure à 09 h 25 révèlent une réécriture de ''retrait'' en ''hésitation''. Une copie faite irrégulièrement par un membre d''équipe correspond à l''original archivé. Le médecin, qui avait demandé l''arrêt à 09 h 19, chute à 09 h 47 et présente ensuite une amnésie plausible. Les décisions datées et leurs auteurs doivent être reconstruits sans tirer de conclusion automatique du trouble de mémoire.', 'REFUS CONSERVÉ', 'Une copie conserve le refus initial. Le médecin avait demandé l’arrêt avant sa chute et son amnésie.'),
('010', 'LA PORTE SE REFERME À 12 H 18', 'Un registre papier et des traces électroniques ne concordent pas sur l''accès d''un prestataire la veille. Nora a préparé un contrôle de conformité pour 14 h. Un badge du service et le contact de porte indiquent une fermeture à 12 h 18, mais l''identité du porteur effectif, sa connaissance de la défaillance intérieure et son intention restent à vérifier.', 'LA PORTE SE REFERME À 12 H 18', 'À 12 h 18, la porte de Nora se ferme. Un badge de service est utilisé, mais on ignore par qui.'),
('010', 'LE PASSAGE DE 13 H 54', 'Une tournée logistique dans le secteur n''était pas mandatée pour ouvrir la réserve. À 13 h 54, une autorisation d''astreinte ouvre, puis le vantail est rabattu. Un passage d''astreinte non associé à un ordre de mission apparaît peu avant ; ces pièces peuvent expliquer la présence du second intervenant sans démontrer ce qu''il a compris en voyant Nora.', 'LE PASSAGE DE 13 H 54', 'À 13 h 54, une autorisation d’astreinte ouvre puis referme la réserve, sans mission prévue pour le faire.'),
('010', 'CE QUE L''OUVERTURE CHANGE', 'La caméra muette montre Nora vivante au seuil pendant l''ouverture de 13 h 54. Une trace de service de la veille et une déclaration de contrôle rapprochent l''agent d''astreinte du passage irrégulier que Nora voulait signaler ; les enquêteurs doivent vérifier sa connaissance personnelle, l''absence d''ordre et les deux fermetures distinctes.', 'CE QUE L''OUVERTURE CHANGE', 'Une vidéo montre Nora vivante quand la porte s’ouvre à 13 h 54. On ignore ce que l’agent a compris.'),
('010', 'UNE FERMETURE D''ESSAI', 'Une fiche de maintenance signale la poignée intérieure défectueuse, alors qu''un contrôle de service est déclaré effectué le matin. À 12 h 18, la porte se referme après une intervention extérieure, sans preuve de verrouillage commandé. Il faut séparer l''état réel du dispositif, la fiabilité des contrôles déclarés et la connaissance de l''occupation.', 'UNE FERMETURE D''ESSAI', 'À 12 h 18, la porte se referme. La poignée intérieure était défectueuse, sans ordre de verrouiller prouvé.'),
('010', 'UN AVERTISSEMENT NON TRANSMIS', 'À 13 h 37, une collègue demande une vérification après des bruits et l''absence de Nora ; la demande est consultée sans être relayée. À 13 h 54, une dérogation d''astreinte ouvre la réserve, puis le contact de porte revient à fermé. Les capteurs n''indiquent pas si le vantail a été repoussé ou s''il s''est fermé par son rappel mécanique.', 'UN AVERTISSEMENT NON TRANSMIS', 'À 13 h 37, une demande de vérifier Nora est lue mais non transmise. La porte s’ouvre puis se referme à 13 h 54.'),
('010', 'L''OUVERTURE N''A PAS SAUVÉ NORA', 'Un angle vidéo muet permet de distinguer le recul de l''agent, le vantail lâché puis refermé par son ferme-porte. Une feuille de contrôle signée à 9 h 05 est démentie par l''absence de passage au seuil sur la vidéo du créneau indiqué. Après la seconde fermeture, le badge aurait permis d''ouvrir de nouveau ; aucun secours n''a été appelé avant 14 h 10.', 'L''OUVERTURE N''A PAS SAUVÉ NORA', 'À 13 h 54, un agent lâche la porte, qui se referme seule. Il pouvait rouvrir, mais aucun secours n’est appelé avant 14 h 10.'),
('010', 'UNE RESTRICTION INHABITUELLE', 'À 12 h 18, un contact de porte signale un rabattement de vantail. Une modification des badges ordinaires intervient à 12 h 19 et une note d''occupation est modifiée. La seule restriction des badges ne pourrait pas empêcher une sortie intérieure fonctionnelle ; il faut établir l''origine physique de l''enfermement et attribuer les manipulations.', 'UNE RESTRICTION INHABITUELLE', 'La porte se ferme à 12 h 18. Une minute plus tard, les badges ordinaires sont restreints.'),
('010', 'UN MESSAGE PENDANT L''OUVERTURE', 'À 13 h 54, un badge d''astreinte ouvre malgré les restrictions. Une communication interne survient et une consigne de maintenir le local fermé est rapportée ; un message évoque aussi une intervention à venir. Il faut authentifier l''émetteur, les mots réellement reçus et vérifier si une quelconque alerte a effectivement été envoyée.', 'UN MESSAGE PENDANT L''OUVERTURE', 'À 13 h 54, un badge d’astreinte ouvre. Un message demande de garder la pièce fermée. Son auteur reste à identifier.'),
('010', 'DEUX ACTES, UNE MÊME RÉTENTION', 'L''ouverture et la fermeture de 13 h 54 sont établies par la vidéo muette et le capteur. La communication authentifiée comporte une menace et une affirmation de prise en charge prochaine ; les registres du poste de sécurité n''en montrent aucune avant 14 h 10. Il faut distinguer la tromperie du supérieur du choix de l''agent de ne rien vérifier.', 'DEUX ACTES, UNE MÊME RÉTENTION', 'La porte se referme à 13 h 54. Un message promet une intervention, mais aucun secours n’apparaît avant 14 h 10.'),
('011', 'AVIS IGNORÉ', 'H+00, le bureau juridique signale la présence de familles. H+03, le premier officier signe malgré la note civile.', 'AVIS IGNORÉ', 'Au début de l’opération, un juriste signale des familles dans la zone. Trois heures plus tard, un officier signe malgré l’alerte.'),
('011', 'DES DÉCISIONS SUR LE TERRAIN', 'H+15, le commandant local maintient des décisions de terrain qui aggravent les destructions et débordent les consignes reçues.', 'DES DÉCISIONS SUR LE TERRAIN', 'À H+15, le commandant local maintient des actions plus destructrices que ce que les ordres permettaient.'),
('011', 'SUSPENSION RETARDÉE', 'H+18, une alerte crédible est reçue. H+29, la suspension est encore retardée malgré les messages intervenus entre-temps.', 'SUSPENSION RETARDÉE', 'Une alerte arrive à H+18. À H+29, la suspension est toujours retardée.'),
('011', 'LIMITES SIGNÉES', 'H+00, le premier officier signe un ordre limité qui exclut les secteurs habités de l''opération.', 'LIMITES SIGNÉES', 'À H+00, l’ordre signé exclut les zones habitées.'),
('011', 'EXTENSION NON AUTORISÉE', 'H+11, le commandant local franchit le périmètre interdit par une décision prise sans nouvelle autorisation.', 'EXTENSION NON AUTORISÉE', 'À H+11, le commandant local entre dans une zone interdite sans nouvelle autorisation.'),
('011', 'ALERTES ET RAPPORT RETOUCHÉ', 'Entre H+16 et H+26, plusieurs alertes sont reçues. La suspension intervient tard ; à H+36, le rapport local a été édulcoré.', 'ALERTES ET RAPPORT RETOUCHÉ', 'Des alertes arrivent entre H+16 et H+26. La suspension tarde et le rapport est minimisé à H+36.'),
('011', 'UN ORDRE N''EST PAS UN BLANC-SEING', 'H+00, le premier officier approuve une mission risquée mais limitée ; il n''autorise pas l''extension ultérieure.', 'UN ORDRE N''EST PAS UN BLANC-SEING', 'À H+00, un officier valide une mission limitée. Il n’autorise pas son extension.'),
('011', 'INITIATIVE ET AVERTISSEMENT', 'H+10, le responsable local élargit l''opération. H+13, le bureau de suspension reçoit un avertissement précis.', 'INITIATIVE ET AVERTISSEMENT', 'Le commandant local élargit l’opération à H+10. Une alerte arrive au bureau de suspension à H+13.'),
('011', 'UNE ACCUSATION RÉÉCRITE', 'À H+36, le rapport initial a été réécrit par le bureau de suspension pour faire porter l''extension au premier officier.', 'UNE ACCUSATION RÉÉCRITE', 'À H+36, le bureau de suspension modifie le rapport pour accuser l’officier qui avait signé l’ordre initial.'),
('012', 'H+00 — Téléphone consigné', 'À H+00, la direction signe l''ordre de garder Sacha sur place et de lui retirer son téléphone. Le texte vise sa liberté de sortir, sans mentionner de violence.', 'H+00 — Téléphone consigné', 'Au début, la direction ordonne de retenir Sacha et de lui prendre son téléphone. Elle ne demande pas de le frapper.'),
('012', 'H+06 — Coups hors consigne', 'À H+06, un registre médical confirme des blessures apparues sous la garde du responsable de discipline. Le document initial ne contient aucun ordre de frapper Sacha.', 'H+06 — Coups hors consigne', 'Six heures plus tard, Sacha est blessé pendant sa garde. Aucun ordre écrit ne demandait de le frapper.'),
('012', 'H+19 — Un passage volontaire', 'À H+19, une ronde reste sans signature. Sacha fuit peu après par une porte dont le verrou a été laissé libre. Le proche avait surveillé le couloir plusieurs heures.', 'H+19 — Un passage volontaire', 'Vers H+19, une ronde manque au registre. Sacha s’échappe peu après par une porte mal verrouillée.'),
('012', 'H+00 — Parler ou retenir ?', 'La première instruction du dirigeant demande que Sacha reste à proximité pour une discussion. Elle n''évoque pas de porte verrouillée. Un ordre oral ultérieur du responsable impose pourtant un contrôle physique.', 'H+00 — Parler ou retenir ?', 'La direction demande seulement de parler à Sacha. Un responsable ordonne ensuite de le retenir.'),
('012', 'H+11 — Une alerte lue', 'Une notification écrite explique à la direction que Sacha est enfermé contre sa volonté et présente des blessures. Le chef accuse réception à H+11, mais aucun ordre de libération immédiate n''est retrouvé.', 'H+11 — Une alerte lue', 'À H+11, la direction apprend que Sacha est enfermé et blessé. Aucun ordre de le libérer n’apparaît.'),
('012', 'H+19 — Sortir sans autorisation', 'Le proche avait assuré des gardes. Il abandonne discrètement son poste vers H+19, permettant la fuite. Le chef n''avait toujours pas fait acter une décision claire de libération.', 'H+19 — Sortir sans autorisation', 'Vers H+19, un proche quitte sa garde et laisse Sacha s’enfuir. La direction n’a pas ordonné sa libération.'),
('012', 'H+00 — Initiative individuelle', 'Le responsable de discipline consigne le téléphone et retient Sacha avant toute réunion ou signature du dirigeant. Les premiers registres ne mentionnent aucun ordre de la direction.', 'H+00 — Initiative individuelle', 'Un responsable enferme Sacha et prend son téléphone avant toute réunion ou ordre de la direction.'),
('012', 'H+12 — La discrétion exigée', 'La direction apprend à H+12 que Sacha est enfermé et blessé. Une réponse demande de ne pas prévenir l''extérieur pour protéger la communauté ; elle ne commande ni libération ni soins immédiats.', 'H+12 — La discrétion exigée', 'À H+12, la direction sait que Sacha est blessé et enfermé. Elle demande le silence, pas sa libération.'),
('012', 'H+19 — Aider après avoir gardé', 'Le proche occupe le couloir pendant plusieurs rondes, puis laisse un passage libre vers H+19. La sortie ne supprime ni son silence antérieur ni le choix tardif de la direction.', 'H+19 — Aider après avoir gardé', 'Vers H+19, le proche laisse un passage libre à Sacha, après avoir gardé le couloir pendant des heures.'),
('013', 'C1 · Des mandats séparés', 'Les archives du réseau PERSEUS attestent que plusieurs intermédiaires ont travaillé sur le même dossier. Les instructions reçues par le coordinateur évoquent une action violente, sans désigner nommément la victime.', 'C1 · Des mandats séparés', 'PERSEUS a utilisé plusieurs intermédiaires. Le coordinateur a reçu un ordre violent sans nom de victime.'),
('013', 'C2 · La cible connue du seul exécutant', 'Un extrait de correspondance confirme que le tireur connaissait l''identité du président avant les faits. L''enquête ne trouve pas de transmission nominative équivalente adressée au coordinateur.', 'C2 · La cible connue du seul exécutant', 'Le tireur savait que sa cible était le président. Rien ne prouve que le coordinateur connaissait son nom.'),
('013', 'C3 · Une modification postérieure', 'L''historique des accès distingue une autorisation irrégulière préalable et une modification du registre enregistrée après la mort du président. Ces actes concernent le cadre de sécurité.', 'C3 · Une modification postérieure', 'Un accès irrégulier a eu lieu avant l’assassinat. Le registre de sécurité a été modifié après.'),
('013', 'C1 · Une commande sans victime nommée', 'Le contrat reçu par le coordinateur évoque une opération d''intimidation grave. Aucun nom de victime n''y figure. Une seconde instruction, conservée séparément, désigne le président au tireur.', 'C1 · Une commande sans victime nommée', 'Le contrat du coordinateur parle d’intimidation, sans nom de victime. Un autre ordre désigne le président au tireur.'),
('013', 'C2 · Deux circuits financiers', 'Les investigations relèvent deux flux de paiement indépendants : la préparation générale et un versement au cadre de sécurité. Cette séparation contredit l''idée d''une seule chaîne de financement entièrement connue.', 'C2 · Deux circuits financiers', 'Deux paiements différents ont financé la préparation générale et un cadre de sécurité.'),
('013', 'C3 · Une accusation commode', 'Après l''assassinat, le cadre de sécurité accuse le coordinateur d''avoir choisi la cible. Les archives datées établissent que l''information nominative a circulé ailleurs et plus tard.', 'C3 · Une accusation commode', 'Après l’assassinat, le cadre de sécurité accuse le coordinateur. Les archives situent l’information sur la cible ailleurs.'),
('013', 'C1 · Une anomalie antérieure', 'L''historique des accès présente une modification irrégulière antérieure au dernier ordre attribué au réseau. Le cadre de sécurité avait commencé à altérer les documents avant que le coordinateur tente de suspendre la mission.', 'C1 · Une anomalie antérieure', 'Le cadre de sécurité avait déjà modifié les dossiers avant la demande d’arrêt du coordinateur.'),
('013', 'C2 · Une suspension sans accusé', 'Un message du coordinateur demande l''interruption de l''opération après une nouvelle alarmante. Aucun accusé de réception provenant du tireur n''est établi. Le meurtre a lieu malgré la demande.', 'C2 · Une suspension sans accusé', 'Le coordinateur demande l’arrêt de l’opération. Aucun reçu ne montre que le tireur a lu son message.'),
('013', 'C3 · Qui pouvait encore agir ?', 'Le dossier distingue un coordinateur tardivement opposé à l''opération, un tireur n''ayant reçu aucun arrêt confirmé et un responsable de sécurité déjà engagé dans la dissimulation.', 'C3 · Qui pouvait encore agir ?', 'Le coordinateur avait demandé l’arrêt, sans confirmation du tireur. Le cadre de sécurité avait déjà masqué des faits.'),
('014', 'C1 · L''export non autorisé', 'Le relevé d''audit confirme qu''un analyste a extrait plusieurs pages classifiées en dehors du processus prévu. Ces pages ne suffisaient pas, à elles seules, à identifier les onze informateurs.', 'C1 · L''export non autorisé', 'Un analyste a copié des pages secrètes hors procédure. Elles ne suffisaient pas à nommer les onze informateurs.'),
('014', 'C2 · La liste recomposée', 'Des fragments issus de plusieurs dossiers ont été rapprochés après le premier export. Le résultat final contenait les onze identités et les informations de proches, absentes du lot initial.', 'C2 · La liste recomposée', 'Des fragments ont ensuite été réunis en une liste de onze noms, avec des informations sur leurs familles.'),
('014', 'C3 · Vente et dissimulation distinctes', 'Un versement associé à l''officier traitant est confirmé dans le dossier d''enquête. Les retouches du journal de sécurité concernent une anomalie que le responsable voulait cacher, sans prouver qu''il a vendu les identités.', 'C3 · Vente et dissimulation distinctes', 'Un paiement lié à l’officier est retrouvé. Le responsable sécurité a modifié les journaux, sans preuve qu’il ait vendu les noms.'),
('014', 'C1 · Une mesure de protection incomplète', 'Une note interne présente la copie des données comme destinée à protéger en urgence des informateurs menacés. L''autorisation et le contrôle de son destinataire n''ont toutefois jamais été finalisés.', 'C1 · Une mesure de protection incomplète', 'Une note dit que la copie devait protéger des informateurs. Son destinataire n’avait pas encore été vérifié.'),
('014', 'C2 · Un destinataire non vérifié', 'L''officier traitant croyait faire parvenir le dossier à un service d''évacuation habilité. Une vérification administrative ultérieure démontre que le mandat du destinataire n''avait pas été confirmé.', 'C2 · Un destinataire non vérifié', 'L’officier croyait envoyer les noms à un service autorisé. Le mandat de ce service n’était pas confirmé.'),
('014', 'C3 · L''alerte restée sans suite', 'Le responsable sécurité avait reçu une alerte signalant l''incertitude autour de la transmission. Il l''a laissée sans traitement, craignant d''exposer les erreurs de son service. Aucun accord de vente n''a été retrouvé.', 'C3 · L''alerte restée sans suite', 'Le responsable sécurité avait reçu une alerte sur l’envoi, mais ne l’a pas traitée. Aucune vente n’est prouvée.'),
('014', 'C1 · Un accès initialement autorisé', 'Un mandat officiel autorise une consultation limitée des dossiers. L''officier traitant utilise toutefois cet accès à une fin étrangère à la mission, sans être autorisé à communiquer les identités.', 'C1 · Un accès initialement autorisé', 'L’officier pouvait consulter certains dossiers, pas transmettre les noms. Il a utilisé son accès à une autre fin.'),
('014', 'C2 · Une intrusion jamais établie', 'La piste d''une attaque externe repose sur des anomalies d''audit non confirmées. L''enquête relève plutôt des usages de droits déjà accordés et une incapacité interne à suivre correctement les consultations.', 'C2 · Une intrusion jamais établie', 'Aucune attaque externe n’est prouvée. Les données ont surtout été consultées avec des accès déjà autorisés.'),
('014', 'C3 · Détournement et fausse piste', 'L''officier traitant a communiqué des identités hors de son mandat. La sécurité laisse prospérer l''hypothèse d''une intrusion étrangère malgré l''absence de preuve, ce qui détourne l''enquête de l''abus interne.', 'NOMS DIFFUSÉS SANS AUTORISATION', 'Des noms ont été diffusés hors autorisation. Les journaux ne prouvent pas d’intrusion étrangère.'),
('015', 'C1 — L''alerte que la direction a reçue', 'Le dossier contient une recommandation explicite de suspendre ÉLIGIBLES. La direction en accuse réception avant de demander la poursuite. La gravité du risque était connue et discutée.', 'C1 — L''alerte que la direction a reçue', 'La direction reçoit une note demandant d’arrêter ÉLIGIBLES, puis demande de continuer.'),
('015', 'C2 — Signer malgré sa réserve', 'Le clinicien exprime son opposition à la poursuite, puis signe une décision de maintien après un échange avec le responsable du programme. Sa réserve demeure dans une version conservée du dossier.', 'C2 — Signer malgré sa réserve', 'Le clinicien déconseille la poursuite, mais signe finalement le maintien du programme.'),
('015', 'C3 — Après la mort, les formulations changent', 'Le patient décède alors que le programme n''a pas été interrompu. Plusieurs alertes sont atténuées dans des notes produites ensuite. La modification documentaire ne déplace pas la décision initiale du dirigeant.', 'C3 — Après la mort, les formulations changent', 'Après la mort, des notes atténuent les alertes. La décision de poursuivre avait été prise avant.'),
('015', 'C1 — La suspension signée', 'La direction donne son accord pour suspendre ÉLIGIBLES. La décision datée précède la nouvelle signature du clinicien autorisant la poursuite.', 'C1 — La suspension signée', 'La direction avait accepté la suspension. Plus tard, le clinicien a signé pour continuer.'),
('015', 'C2 — Une décision clinique contraire', 'Le clinicien choisit de maintenir le programme malgré l''accord d''arrêt déjà reçu. Aucun nouveau visa du dirigeant ne valide cette poursuite.', 'C2 — Une décision clinique contraire', 'Le clinicien maintient le programme malgré l’ordre d’arrêt. Aucun nouvel accord de la direction n’apparaît.'),
('015', 'C3 — La contradiction maquillée', 'Après le décès, deux décisions opposées sont présentées dans les notes retouchées comme une seule démarche continue, contrairement aux archives originales.', 'DEUX DÉCISIONS CONTRADICTOIRES', 'Après la mort, des notes modifiées présentent deux décisions opposées comme une seule.'),
('015', 'C1 — Une réévaluation sans accusé', 'La direction accepte le principe d''une réévaluation et le clinicien rédige une demande de sortie. Aucun accusé de prise en charge opérationnelle n''est conservé au moment où la décision aurait dû progresser.', 'C1 — Une réévaluation sans accusé', 'La direction accepte une réévaluation et le clinicien demande la sortie. Aucun service ne confirme la prise en charge.'),
('015', 'C2 — Le dossier demeure bloqué', 'Le document nécessaire à la sortie reste au service administratif. Ce blocage prolonge la présence du patient dans ÉLIGIBLES alors même qu''une réévaluation avait été demandée.', 'C2 — Le dossier demeure bloqué', 'Le dossier de sortie reste bloqué à l’administration. Le patient reste dans le programme.'),
('015', 'C3 — Le retard réécrit après le décès', 'Les pièces retravaillées après la mort présentent le retard comme un simple délai de transmission, alors qu''une version antérieure établit que le dossier a été retenu malgré les alertes.', 'C3 — Le retard réécrit après le décès', 'Après le décès, le dossier présente le blocage comme un simple retard d’envoi. L’ancienne version dit autre chose.'),
('016', 'L''image incomplète', 'Le film authentifié prouve l''enlèvement et les humiliations. Il s''interrompt avant les circonstances médicales du décès; la coupure ne suffit pas à attribuer un geste mortel.', 'L''image incomplète', 'La vidéo montre l’enlèvement et les humiliations, mais s’arrête avant les faits qui ont causé la mort.'),
('016', 'La période hors champ', 'Les accès et la caméra du palier situent l''organisateur hors de la zone critique. L''exécutant demeure seul au dernier étage après l''arrêt de la vidéo.', 'La période hors champ', 'L’organisateur a quitté l’étage avant la fin de la vidéo. L’exécutant y reste seul.'),
('016', 'La cause du décès', 'L''autopsie révèle une lésion létale postérieure à la coupure, distincte des violences filmées. Une trace sur l''objet associé recoupe la présence de l''exécutant, seul durant la fenêtre de décès.', 'BLESSURE APRÈS LA VIDÉO', 'Une blessure mortelle apparaît après la coupure. L’objet et les accès donnent des pistes sur la personne présente.'),
('016', 'C1 · Une séquence interrompue', 'La vidéo montre la détention et les violences, mais s''arrête sans enregistrer le meurtre. Le film ne permet pas de décider qui a frappé après la coupure.', 'C1 · Une séquence interrompue', 'La vidéo montre les violences, mais pas le meurtre. On ignore qui a frappé après la coupure.'),
('016', 'C2 · Un retour dissimulé', 'Le premier départ de l''organisateur est attesté. Un autre relevé démontre pourtant sa présence de nouveau sur les lieux après l''arrêt de la caméra.', 'C2 · Un retour dissimulé', 'L’organisateur quitte les lieux, puis revient après l’arrêt de la caméra.'),
('016', 'C3 · L''alibi contredit par un témoin', 'L''exécutant a assisté au retour et au geste mortel de l''organisateur. Son récit de départ définitif est contredit. L''intermédiaire voulait faire arrêter la scène sans connaître le retour.', 'C3 · L''alibi contredit par un témoin', 'Un témoin contredit l’alibi de l’organisateur. Les relevés confirment son retour.'),
('016', 'La période hors champ', 'Le premier départ de l''organisateur est attesté. Un second accès indépendant démontre son retour après la coupure pendant que l''exécutant est encore sur place.', 'La période hors champ', 'Après un premier départ, l’organisateur revient sur place. L’exécutant y est encore.'),
('016', 'La cause du décès', 'Les constatations médico-légales établissent une lésion létale après la coupure. Des traces matérielles recoupées avec les accès relient le geste à l''organisateur revenu sur les lieux.', 'BLESSURE APRÈS LA VIDÉO', 'Une blessure mortelle apparaît après la coupure. Des traces situent l’organisateur revenu pendant cette période.'),
('016', 'L''image incomplète', 'La vidéo établit la séquestration et la sédation. Les derniers plans montrent déjà une dégradation de l''état de la victime, sans préciser sa cause médicale définitive.', 'L''image incomplète', 'La vidéo montre la victime retenue et droguée. Son état se dégrade avant la coupure.'),
('016', 'La période hors champ', 'L''exécutant demeure auprès de la victime en détresse après l''arrêt du film. Le journal des communications ne relève aucun appel aux secours pendant une fenêtre d''intervention utile.', 'La période hors champ', 'L’exécutant reste auprès de la victime après la coupure. Aucun appel aux secours n’est enregistré.'),
('016', 'La cause du décès', 'L''autopsie et la toxicologie attribuent le décès au cumul des violences et de la sédation. Elles ne retrouvent pas de blessure fatale nouvelle après le film. L''absence d''alerte a supprimé une possibilité d''assistance.', 'CAUSE MÉDICALE', 'L’autopsie relie la mort aux violences et aux sédatifs. Aucune nouvelle blessure mortelle n’est trouvée après la vidéo.'),
('017', 'L''EMPREINTE D''UNE CONTRAINTE', 'Le rapport médico-légal décrit une compression thoracique et une détresse respiratoire survenues durant la garde. Une photographie de constat et une déposition concordent sur la position de maintien imposée par le gardien. La seule présence d''une blessure ne suffit pas à identifier qui a ordonné le geste.', 'L''EMPREINTE D''UNE CONTRAINTE', 'La victime a été maintenue de force et a eu du mal à respirer. Une photo et un témoignage confirment la position imposée.'),
('017', 'L''ALERTE REÇUE', 'Une note d''alerte portant une heure de réception et le journal des communications établissent que l''organisateur a été averti d''une détresse grave pendant que le captif était vivant. Aucune demande d''assistance n''apparaît ensuite dans le registre. Les traces prouvent le report, sans garantir qu''un secours aurait sauvé la personne.', 'L''ALERTE REÇUE', 'L’organisateur avait reçu une alerte sur le captif encore vivant. Aucun appel aux secours n’apparaît après.'),
('017', 'L''ARGENT APRÈS LA MORT', 'Le certificat d''intervention situe le décès avant la première connexion de l''intermédiaire. Le relevé financier et le reçu de libération du survivant sont postérieurs. Ils documentent l''achat d''un silence, mais ne placent pas l''intermédiaire au moment de la contrainte ni au moment de l''alerte. Les trois horodatages sont de sources distinctes.', 'L''ARGENT APRÈS LA MORT', 'Un paiement suit la mort, avant la libération du survivant. Il ne place pas l’intermédiaire au moment du décès.'),
('017', 'LE BLESSÉ POUVAIT ENCORE ÊTRE PRIS EN CHARGE', 'Une fiche d''observation datée et un rapport médical décrivent le captif vivant après une violence grave. Le dossier établit qu''une intervention restait matériellement possible, pas qu''elle aurait certainement sauvé le captif.', 'LE BLESSÉ POUVAIT ENCORE ÊTRE PRIS EN CHARGE', 'La victime était encore vivante après de graves violences. Des secours restaient possibles, sans garantie de survie.'),
('017', 'UNE OFFRE ÉCRITE, UN REFUS CONSIGNÉ', 'Le registre de transport mentionne un véhicule disponible, une destination d''accueil et une proposition d''évacuation reçue par l''organisateur. Une instruction de poursuivre la rétention est horodatée quelques minutes plus tard. Ce refus est distinct du coup initial porté par le gardien.', 'UNE OFFRE ÉCRITE, UN REFUS CONSIGNÉ', 'Un véhicule et un lieu d’accueil avaient été proposés pour évacuer la victime. L’organisateur a ordonné de la garder.'),
('017', 'LE RETARD A UN AUTEUR', 'Le relevé des ordres lie expressément la prolongation à l''exigence de négociation de l''organisateur ; l''offre d''assistance précède la détérioration terminale. La première intervention de l''intermédiaire est postérieure au décès. Les pièces établissent la responsabilité du refus sans inventer un homicide intentionnel.', 'LE RETARD A UN AUTEUR', 'L’organisateur prolonge la détention malgré une offre de secours. L’intermédiaire intervient après la mort.'),
('017', 'UNE PREMIÈRE SORTIE ENVISAGÉE', 'Le registre de garde enregistre une discussion sur la sortie des deux captifs, puis un maintien prolongé. Il existe une rupture entre la date de la sortie initialement prévue et le moment de l''aggravation du captif. L''identité du demandeur n''est pas encore connue.', 'UNE PREMIÈRE SORTIE ENVISAGÉE', 'La sortie des deux captifs avait été discutée, puis retardée. On ignore qui l’a demandé.'),
('017', 'L''ORDRE VIENT D''UNE NÉGOCIATION', 'Une communication authentifiée situe le contact de l''intermédiaire avant le décès. Le message porte sur une nouvelle concession exigée du comptable ; une instruction de ne pas libérer les captifs suit cette demande. Les journaux de transmission relient les deux événements, sans attribuer au négociateur le geste physique du gardien.', 'L''ORDRE VIENT D''UNE NÉGOCIATION', 'Un intermédiaire contacte le groupe avant la mort pour exiger davantage. Un ordre de garder les captifs suit.'),
('017', 'LE MESSAGE EFFACÉ AVAIT UNE DATE', 'L''archive technique conserve l''horodatage antérieur au décès du message envoyé par l''intermédiaire. Le système journalise aussi sa suppression ultérieure. Le retour du conducteur et le reçu d''accord de silence sont postérieurs à la mort. Le mensonge selon lequel toute intervention financière serait intervenue après la mort est matériellement réfuté.', 'LE MESSAGE EFFACÉ AVAIT UNE DATE', 'Un message de l’intermédiaire date d’avant la mort, puis a été effacé. Le reçu d’accord de silence est postérieur.'),
('018', 'DES PASSAGES NON SIMULTANÉS', 'Les relevés distinguent plusieurs visites. Une présence collective des neuf anciens résidents n''est attestée par rien.', 'DES PASSAGES NON SIMULTANÉS', 'Les neuf anciens résidents ne sont jamais vus ensemble. Les relevés montrent plusieurs visites séparées.'),
('018', 'LA TABLE A BOUGÉ', 'La disposition de la table est postérieure à un désordre; la seule manipulation des objets ne désigne aucun auteur.', 'LA TABLE A BOUGÉ', 'La table a été déplacée après que la pièce a été dérangée. Cela ne dit pas qui a tué la victime.'),
('018', 'LA CHRONOLOGIE À RECONSTRUIRE', 'Une arrivée tardive et une première confrontation apparaissent distinctes, mais les déclarations doivent encore être confrontées.', 'DEUX MOMENTS DISTINCTS', 'Une personne arrive tard, après une première confrontation. On ignore encore le lien entre les deux moments.'),
('018', 'DEUX DISCUSSIONS SÉPARÉES', 'Plusieurs rencontres avec le directeur sont attestées; aucune n''est encore identifiée comme celle du geste mortel.', 'DEUX DISCUSSIONS SÉPARÉES', 'Plusieurs personnes ont rencontré le directeur. On ignore laquelle l’a vu au moment du meurtre.'),
('018', 'UN DIFFÉREND COMPTABLE', 'Un litige financier se rattache à la période entourant les violences, sans attribution personnelle définitive.', 'UN DIFFÉREND COMPTABLE', 'Une dispute d’argent apparaît pendant les événements, sans preuve sur son responsable.'),
('018', 'UNE SCÈNE COMPOSÉE PLUS TARD', 'Les assiettes ont été disposées après la phase mortelle; cette intervention ne prouve pas qui a tué.', 'UNE SCÈNE COMPOSÉE PLUS TARD', 'Les assiettes ont été placées après la mort. Leur disposition ne désigne pas le meurtrier.'),
('018', 'UN RENDEZ-VOUS CONTESTÉ', 'Des communications évoquent une pression collective sur le directeur; leur portée exacte reste à établir.', 'UN RENDEZ-VOUS CONTESTÉ', 'Des messages montrent que plusieurs personnes voulaient faire pression sur le directeur.'),
('018', 'DES ARRIVÉES DISTINCTES', 'Les passages et les traces de lutte suggèrent des interventions séparées; les données ne révèlent pas directement l''auteur.', 'DES ARRIVÉES DISTINCTES', 'Les arrivées et les traces de lutte montrent des passages distincts, sans identifier qui a tué.'),
('018', 'UN SYMBOLE POSTÉRIEUR', 'La table a été dressée après la mort; un projet antérieur ne rend pas automatiquement chaque participant responsable du geste fatal.', 'UN SYMBOLE POSTÉRIEUR', 'La table a été dressée après la mort. Un projet commun ne prouve pas que tous ont participé au meurtre.'),
('019', 'DEUX VERSIONS', 'La chemise publique du lanceur d''alerte ne correspond pas à l''inventaire de son dossier intégral. Certaines annexes sont manquantes.', 'DEUX VERSIONS', 'La version publique du dossier financier manque plusieurs annexes présentes dans la copie complète.'),
('019', 'UNE INTERCEPTION HORS REGISTRE', 'Le dispositif de sécurité a été modifié dans un couloir technique. La mission commandée et la manière dont elle a été exécutée demandent deux vérifications indépendantes.', 'UNE INTERCEPTION HORS REGISTRE', 'La sécurité a changé les accès d’un couloir technique. On ignore qui a demandé ce changement.'),
('019', 'DES COMPTES ET DES COPIES', 'Des prestations de sécurité non justifiées figurent dans l''annexe complète. Une suppression administrative datée après le décès concerne un autre ensemble de pièces.', 'DES COMPTES ET DES COPIES', 'Des dépenses de sécurité non justifiées figurent dans une annexe. D’autres pièces ont été supprimées après la mort.'),
('019', 'UN ENTRETIEN HORS PROGRAMME', 'L''ordre du jour ne mentionne pas une rencontre privée que deux personnels du gala disent avoir préparée. Les documents ne décrivent pas la teneur de cette discussion.', 'UN ENTRETIEN HORS PROGRAMME', 'Deux employés ont préparé une réunion privée absente du programme du gala.'),
('019', 'LE SALON SANS SURVEILLANCE', 'La ronde a été déplacée tandis qu''un salon réservé était ouvert. Les journaux des accès et la coupure vidéo doivent être interprétés séparément.', 'LE SALON SANS SURVEILLANCE', 'Une ronde de sécurité a été déplacée pendant qu’un salon privé restait ouvert. La vidéo est coupée.'),
('019', 'DEUX JOURNAUX D''ACCÈS', 'Une copie indépendante montre une modification tardive du registre de sécurité. Elle doit être rapprochée de l''heure de la rencontre privée et des issues réservées.', 'DEUX JOURNAUX D''ACCÈS', 'Une copie indépendante montre un changement tardif du registre des accès.'),
('019', 'DEUX VERSIONS', 'L''inventaire annoncé avant le gala comporte des annexes absentes du dossier destiné à la presse. Plusieurs services possédaient des copies partielles.', 'DEUX VERSIONS', 'Le dossier remis à la presse manque plusieurs annexes présentes dans l’inventaire initial.'),
('019', 'DES JOURNAUX INCOMPATIBLES', 'Un même passage est décrit différemment dans un relevé administratif et dans une trace technique. Leur origine et leur date de création doivent être comparées.', 'DES JOURNAUX INCOMPATIBLES', 'Le même passage apparaît différemment dans un registre administratif et un relevé technique.'),
('019', 'UN EXPORT RECONSTITUÉ', 'Le relevé transmis après le décès contient une modification non répercutée dans la sauvegarde d''origine. Le dossier complet éclaire l''intérêt d''une telle intervention.', 'UN EXPORT RECONSTITUÉ', 'Un relevé envoyé après la mort a été modifié. La sauvegarde d’origine ne contient pas ce changement.'),
('020', 'DÉPART DE FEU PROVOQUÉ', 'L’analyse établit un départ de feu volontaire et limité à l’origine, distinct des mécanismes ayant piégé la foule.', 'DÉPART DE FEU PROVOQUÉ', 'Le feu a commencé volontairement, mais était limité au départ. D’autres problèmes ont piégé la foule.'),
('020', 'LES ISSUES RESTENT RESTREINTES', 'Des avertissements sur des portes inutilisables étaient connus avant le gala ; la direction maintient les restrictions.', 'LES ISSUES RESTENT RESTREINTES', 'La direction connaissait le problème des sorties avant le gala, mais a maintenu les restrictions.'),
('020', 'L’ALERTE N’EST PAS SUIVIE', 'Le coordinateur prend connaissance des premiers signes sans ordonner immédiatement l’évacuation ; plusieurs facteurs amplifient le bilan.', 'L’ALERTE N’EST PAS SUIVIE', 'Le coordinateur voit les premiers signaux, mais n’ordonne pas tout de suite l’évacuation.'),
('020', 'LE PLAN ET SES LIMITES', 'Le plan des espaces montre plusieurs cheminements possibles vers l''extérieur. Mais la capacité d''évacuation réelle dépendait aussi de restrictions de service appliquées avant la soirée.', 'LE PLAN ET SES LIMITES', 'Le plan prévoit plusieurs sorties, mais des restrictions du service limitaient leur utilisation.'),
('020', 'UNE CONSIGNE NON LEVÉE', 'Une note de gestion mentionne des issues secondaires restreintes et des recommandations de vérification encore ouvertes. Le document ne précise pas leur état pendant l''alarme.', 'UNE CONSIGNE NON LEVÉE', 'Une note signale des issues restreintes et des contrôles non terminés. Leur état pendant l’alarme reste inconnu.'),
('020', 'LES CONTRÔLES AVANT LE BAL', 'Les journaux de préparation font apparaître une réserve technique non levée et un contrôle d''accès raccourci. Il faut déterminer qui disposait de chaque information.', 'LES CONTRÔLES AVANT LE BAL', 'Une réserve technique restait ouverte et un contrôle d’accès avait été écourté avant le gala.'),
('020', 'LES PREMIERS SIGNAUX', 'Les premiers témoignages décrivent un incident localisé avant une alerte plus importante. Les récits ne concordent pas encore sur l''instant du départ du feu.', 'LES PREMIERS SIGNAUX', 'Les premiers témoins parlent d’un incident local, puis d’une alerte plus grave. Ils ne s’accordent pas sur le début.'),
('020', 'LES VERSIONS DU RAPPORT', 'Une expertise recoupe l''heure des accès et les traces du foyer : une intervention volontaire provoque le départ du feu, indépendamment des défauts de protection et des restrictions de sortie. Le constat ne prouve aucune intention de provoquer le bilan humain.', 'LES VERSIONS DU RAPPORT', 'L’expertise montre un départ de feu volontaire. Les défauts de sécurité ont ensuite aggravé le danger.'),
('020', 'DEUX CHRONOLOGIES À RECROISER', 'Les journaux montrent un premier signal interprété comme incident local, puis des alertes plus graves avant l''annonce générale. Le délai relève d''une appréciation insuffisante du risque, sans ordre conservé de privilégier un groupe d''invités.', 'DEUX CHRONOLOGIES À RECROISER', 'Une première alerte a été prise pour un incident mineur. L’alarme générale a été déclenchée plus tard.'),
('020', 'AUCUNE MISE À FEU VOLONTAIRE PROUVÉE', 'Une défaillance accidentelle documentée précède l''incendie. La présence de l''activiste ne suffit pas à désigner un auteur du feu.', 'AUCUNE MISE À FEU VOLONTAIRE PROUVÉE', 'Une panne technique a précédé le feu. La présence de l’activiste ne prouve pas qu’il l’ait allumé.'),
('020', 'DES SORTIES BLOQUÉES MALGRÉ LES SIGNALEMENTS', 'Les instructions de gestion maintiennent des issues fermées alors que des réserves techniques avaient été remises.', 'DES SORTIES BLOQUÉES MALGRÉ LES SIGNALEMENTS', 'Des sorties sont restées fermées malgré les signalements de problèmes.'),
('020', 'UNE FAUSSE ASSURANCE DE SÉCURITÉ', 'Le rapport de contrôle favorable, malgré ses lacunes, retarde la décision du coordinateur ; l''absence d''incendie volontaire n''efface pas les responsabilités humaines.', 'UNE FAUSSE ASSURANCE DE SÉCURITÉ', 'Un rapport trop rassurant a retardé l’évacuation. Le feu accidentel n’efface pas les fautes de sécurité.'),
('020', 'LE PLAN ET SES LIMITES', 'Le plan du bâtiment prévoit plusieurs sorties secondaires, mais leur disponibilité effective n''avait pas été confirmée dans la configuration retenue pour la réception.', 'LE PLAN ET SES LIMITES', 'Le plan prévoit plusieurs sorties. Leur ouverture le soir du bal n’avait pas été confirmée.'),
('020', 'UNE CONSIGNE NON LEVÉE', 'Une demande de contrôle final des accès avait été inscrite au planning. Un autre document indique que la ronde n''a finalement pas été menée.', 'UNE CONSIGNE NON LEVÉE', 'Un contrôle final des sorties était prévu, mais la ronde n’a pas été faite.'),
('020', 'LES CONTRÔLES AVANT LE BAL', 'Une première note signale des réserves sur la sécurité technique alors qu''un document diffusé aux organisateurs mentionne une conformité sans réserve explicative.', 'LES CONTRÔLES AVANT LE BAL', 'Une note signalait des problèmes techniques. Le rapport transmis aux organisateurs disait que tout était conforme.'),
('020', 'LES PREMIERS SIGNAUX', 'Des témoignages placent l''activiste à proximité d''une zone de service avant la fumée; ils ne décrivent aucun geste permettant d''attribuer le départ du feu.', 'LES PREMIERS SIGNAUX', 'L’activiste était près d’une zone de service avant la fumée. Personne ne l’a vu allumer le feu.'),
('020', 'LES VERSIONS DU RAPPORT', 'Une expertise indépendante des composants du foyer confirme une défaillance technique accidentelle. La présence antérieure de l''activiste ne permet pas de lui attribuer un geste d''allumage; un rapport trop favorable avait masqué des anomalies.', 'LES VERSIONS DU RAPPORT', 'L’expertise attribue le feu à une panne. La présence de l’activiste ne prouve rien sur son départ.'),
('020', 'DEUX CHRONOLOGIES À RECROISER', 'Les alarmes et les communications documentent un retard de réaction nourri par une confiance injustifiée dans le rapport de conformité; aucun avis urgent compris puis volontairement écarté n''est établi.', 'DEUX CHRONOLOGIES À RECROISER', 'Les alarmes ont été traitées trop tard à cause d’un rapport de sécurité trop rassurant.'),
('020', 'UNE CONSIGNE NON LEVÉE', 'Une note de production et des réserves anciennes ne sont pas intégralement reprises dans la version publique du programme du gala. Il faut en vérifier la portée et les signataires.', 'UNE CONSIGNE NON LEVÉE', 'Des avertissements de sécurité ne figurent pas dans la version publique du programme du gala.'),
('020', 'LES PREMIERS SIGNAUX', 'Le journal d''alarme et les premières dépositions montrent une différence entre la perception d''un incident scénique et la compréhension d''un danger réel.', 'LES PREMIERS SIGNAUX', 'Les premiers signaux ont été pris pour un problème de scène, puis le danger a été reconnu.'),
('020', 'DEUX CHRONOLOGIES À RECROISER', 'Le journal de réception, l''avis technique urgent et les communications d''ordre montrent que la coordination a différé l''annonce générale pour maintenir le passage d''une délégation VIP. Ce choix suit la compréhension du danger.', 'ALARME RETARDÉE POUR LES VIP', 'Des messages montrent que l’alarme a été repoussée pendant le passage d’une délégation VIP.'),
('020', 'LE PLAN ET SES LIMITES', 'Le plan d''accueil distingue les accès ordinaires des couloirs réservés aux donateurs. Les circulations imposées par le protocole ont modifié la capacité effective de sortie.', 'LE PLAN ET SES LIMITES', 'Le plan séparait les sorties normales et les couloirs réservés aux donateurs. Cela réduisait le passage possible.'),
('020', 'LES CONTRÔLES AVANT LE BAL', 'Un contrôle des installations n''était pas clôturé avant le numéro final. Le document ne démontre pas directement quel événement a commencé l''incendie.', 'LES CONTRÔLES AVANT LE BAL', 'Un contrôle des installations n’était pas fini avant le dernier numéro.'),
('020', 'LES VERSIONS DU RAPPORT', 'Une copie indépendante du programme de régie, croisée avec les traces du foyer, établit qu''un effet scénique autorisé tardivement a provoqué accidentellement l''incendie. L''activiste n''a pas participé à son activation.', 'LES VERSIONS DU RAPPORT', 'Une copie du programme indique qu’un effet de scène a été autorisé tard. L’expertise le relie à l’incendie.'),
('002', 'APPELS IGNORÉS', 'Plusieurs appels de Léon restent sans réponse le soir de sa mort, dont certains destinés à B.', 'APPELS IGNORÉS', 'Léon a appelé plusieurs fois un proche avec qui il se disputait. Ces appels sont restés sans réponse.'),
('002', 'DERNIER REFUGE', 'Des messages montrent que Léon considérait encore B comme l''une des seules personnes capables de le comprendre.', 'DERNIER REFUGE', 'Malgré leurs disputes, Léon comptait encore sur ce proche pour le comprendre.'),
('004', 'PASSAGE DEVANT L''IMMEUBLE', 'Une caméra de rue montre un véhicule compatible avec celui de C passant devant l''immeuble.', 'PASSAGE DEVANT L''IMMEUBLE', 'Une caméra montre une voiture ressemblant à celle du proche de Sofia qui habitait le quartier passer devant son immeuble.'),
('019', 'LE DOSSIER ATTENDU', 'La victime avait annoncé une remise de pièces financières; les copies disponibles ne coïncident pas toutes.', 'LE DOSSIER ATTENDU', 'La victime devait remettre des documents financiers au gala. Les copies trouvées ne correspondent pas toutes.'),
('019', 'LE DISPOSITIF MODIFIÉ', 'Des déplacements et accès techniques ont changé pendant la soirée. Leur origine doit être vérifiée.', 'LE DISPOSITIF MODIFIÉ', 'Pendant le gala, des trajets et des accès ont changé. On ignore qui l’a demandé.'),
('019', 'LES COPIES CONTRADICTOIRES', 'Plusieurs versions des registres et des documents circulent; elles nécessitent des recoupements.', 'LES COPIES CONTRADICTOIRES', 'Plusieurs copies des mêmes comptes ne contiennent pas les mêmes informations.'),
('020', 'UN BÂTIMENT OCCUPÉ', 'La capacité des passages et les règles de circulation exigent une vérification indépendante.', 'SORTIES OUVERTES TROP TARD', 'Plusieurs sorties de secours du Bal des Fondateurs ont été ouvertes avec retard.'),
('020', 'DES RÉSERVES À CONTRÔLER', 'Plusieurs éléments techniques doivent être rapprochés des documents de préparation.', 'TRAVAUX NON TERMINÉS', 'Des travaux étaient encore en cours avant l’incendie. Leur rôle dans la propagation reste incertain.'),
('020', 'UNE CHRONOLOGIE À VÉRIFIER', 'Le traitement des alertes et la diffusion des instructions doivent être confrontés aux journaux.', 'ALARME RETARDÉE', 'L’alarme générale a été déclenchée après les premiers signaux de danger.'),
('023', 'L’APPEL', 'Adriano Verri a été touché. Son état dépendra des décisions et protections prises autour de la Table.', 'ADRIANO BLESSÉ', 'Un appel confirme qu’Adriano Verri est blessé. On ignore qui l’a attaqué et la gravité de ses blessures.'),
('024', 'CE QUI EST DÉJÀ CONNU', 'Une partie des informations proposées par le détenu figure déjà dans le dossier. Les répéter réduit peu la peine tout en pouvant augmenter son exposition.', 'CE QUI EST DÉJÀ CONNU', 'Paolo Serra propose des informations que les enquêteurs possèdent déjà en partie.'),
('024', 'LA PROTECTION', 'La protection n’est pas automatique. Elle dépend d’un accord réellement accepté et de la valeur des informations fournies.', 'PROTECTION DEMANDÉE', 'Paolo Serra demande une protection. Les documents ne disent pas si elle lui a été accordée.'),
('025', 'LES ORDRES', 'Plusieurs décisions attribuées à Vittorio ne possèdent aucune formulation explicite. Il faut reconstruire ce qu’il a demandé, ce qu’il a seulement accepté et ce que ses hommes ont anticipé.', 'ORDRES ATTRIBUÉS AU DON', 'Vittorio a approuvé certaines décisions. D’autres lui sont attribuées sans preuve qu’il les ait ordonnées.'),
('025', 'LES AUDIENCES', 'Le Don peut convoquer un membre, l’écouter puis décider de le protéger, le surveiller, l’écarter ou autoriser une sanction. Il ne reçoit pas pour autant la vérité privée de ce joueur.', 'SANCTIONS SANS ORDRE', 'Des membres ont été protégés ou punis au nom de Vittorio. Pour certains cas, aucun ordre de lui n’a été retrouvé.'),
('025', 'LE SOMMET', 'Les dossiers précédents convergent vers le même paradoxe : plus le pouvoir est élevé, moins les ordres doivent être explicites.', 'PAIEMENTS ET VIOLENCES', 'Des comptes relient des paiements à Vittorio. Ils ne disent pas toujours qui a demandé les violences.'),
('027', 'DÉTENTION CLANDESTINE', 'Des témoignages concordants confirment que des prisonniers ont été détenus et maltraités sous l’autorité du deuxième suspect.', 'DÉTENTION CLANDESTINE', 'Des prisonniers ont été maltraités dans le service où travaillait l’agent chargé des détentions du FDR.'),
('027', 'SOURCE TROP PRÉCISE', 'Le troisième suspect fournit spontanément plusieurs détails exacts sur des cadres rivaux, mais beaucoup moins sur ses propres proches.', 'SOURCE TROP PRÉCISE', 'Le cadre supérieur du FDR décrit en détail ses rivaux, mais parle peu de ses alliés.'),
('027', 'INTÉRÊT PERSONNEL', 'Un échange antérieur prouve que le troisième suspect considérait déjà les cadres de la zone comme ses principaux rivaux.', 'INTÉRÊT PERSONNEL', 'Un ancien échange montre que le cadre supérieur du FDR voyait déjà ces chefs comme ses rivaux.'),
('027', 'LA VÉRITÉ PEUT ÊTRE UNE ARME', 'La majorité des informations livrées par le troisième suspect sont factuellement exactes. Leur sélection, elle, favorise systématiquement la disparition de ses rivaux.', 'LA VÉRITÉ PEUT ÊTRE UNE ARME', 'Les informations du cadre supérieur sont souvent justes, mais concernent surtout ses rivaux.'),
('028', 'LE TROISIÈME ATTEND', 'Le troisième suspect ne demande ni protection ni évacuation malgré la dégradation du périmètre. Son calme n’établit rien, mais il contredit son récit de simple exécutant.', 'AUCUNE DEMANDE DE PROTECTION', 'Le cadre fidèle au FDR ne demande ni protection ni évacuation malgré la menace.'),
('029', 'PAIEMENT APRÈS LES FAITS', 'Un transfert financier est effectué après une exécution et relie le premier suspect au réseau.', 'PAIEMENT APRÈS LES FAITS', 'Un virement après une exécution relie l’intermédiaire financier au cartel.'),
('029', 'ORDRE AMBIGU', 'Un message du deuxième suspect demande de faire peur sans préciser la violence attendue.', 'ORDRE AMBIGU', 'Le responsable local a écrit « faire peur ». Il n’a pas précisé jusqu’où aller.'),
('029', 'COOPÉRATION', 'Le troisième suspect livre un lieu vérifiable et gagne en crédibilité.', 'COOPÉRATION', 'L’exécutant donne un lieu. Les enquêteurs confirment qu’il existe.'),
('031', 'LE DOSSIER', 'Recoupez les déclarations des trois chefs avec les pièces reçues par le bureau.', 'ORDRE DE L’EMBUSCADE', 'Six agents américains ont été tués dans une embuscade. On ignore encore lequel des trois chefs a ordonné l’attaque.'),
('032', 'LISTE SIGNÉE', 'Une liste d’arrestations porte la signature du premier suspect.', 'LISTE SIGNÉE', 'Une liste d’arrestations porte la signature du chef administratif.'),
('032', 'DÉTENTION PROLONGÉE', 'Des registres montrent des prolongations sans ordre écrit validées par le deuxième suspect.', 'DÉTENTION PROLONGÉE', 'Le responsable de la sécurité a prolongé des détentions sans ordre écrit.'),
('032', 'NOTE DU PALAIS', 'Une note du troisième suspect désigne un opposant comme priorité.', 'NOTE DU PALAIS', 'Une note du conseiller du palais désigne un opposant comme cible prioritaire.'),
('032', 'CORRECTION MANUSCRITE', 'Le premier suspect modifie une liste après avoir été informé d’une détention abusive.', 'CORRECTION MANUSCRITE', 'Le chef administratif a changé une liste après avoir appris qu’une détention était abusive.'),
('032', 'CHAÎNE', 'Les archives permettent de séparer cible politique, ordre administratif et exécution sécuritaire.', 'TROIS ÉTAPES', 'Les archives séparent trois faits : un opposant désigné, un ordre administratif, puis une arrestation.'),
('033', 'NOMINATION', 'Une nomination contestée est maintenue par le deuxième suspect.', 'NOMINATION', 'Le parent de la famille qui est ministre a maintenu une nomination contestée.'),
('033', 'AGENDA PRIVÉ', 'Des rendez-vous montrent que le troisième suspect était consulté avant plusieurs décisions.', 'AGENDA PRIVÉ', 'Le conseiller familial était consulté avant plusieurs décisions, malgré sa fonction officielle limitée.'),
('033', 'POUVOIR RÉEL', 'Les décisions les plus sensibles convergent vers l’avis du troisième suspect malgré son faible titre officiel.', 'POUVOIR RÉEL', 'Plusieurs décisions sensibles ont suivi des réunions avec le conseiller familial, malgré son faible titre officiel.'),
('035', 'DERNIER DÉPLACEMENT', 'Un véhicule lié au troisième suspect transporte M-17 quelques heures avant sa mort.', 'DERNIER DÉPLACEMENT', 'Un véhicule lié au relais logistique de CERBÈRES transporte M-17 quelques heures avant sa mort.'),
('036', 'RELAIS CERBÈRES', 'Le troisième suspect est relié à une identité déjà présente dans le dossier M-17.', 'RELAIS CERBÈRES', 'Un intermédiaire de CERBÈRES est lié à une identité déjà apparue dans le dossier M-17.'),
('038', 'LISTE DÉTRUITE', 'Le troisième suspect détruit une liste de contacts après la mort de M-17.', 'LISTE DÉTRUITE', 'L’opérateur de CERBÈRES a détruit une liste de contacts après la mort de M-17.'),
('039', 'GARDE DU SITE', 'Aucun élément n’établit que le deuxième suspect connaissait l’ensemble de l’objectif stratégique lorsqu’il a accepté le transfert de contrôle.', 'GARDE DU SITE', 'Rien ne prouve que le chef de la sécurité connaissait tout l’objectif d’ORPHÉE lors du transfert.'),
('039', 'OPTION DE CRISE', 'Le premier suspect a préparé une option politique de dernier recours sans ordre légal confirmé.', 'OPTION DE CRISE', 'Le coordinateur d’ORPHÉE a préparé une solution politique d’urgence sans autorisation légale connue.'),
('039', 'TENTATIVE BLOQUÉE', 'Une demande institutionnelle visant à reprendre le contrôle d’ORPHÉE a été bloquée par le troisième suspect.', 'TENTATIVE BLOQUÉE', 'Le relais politique de CERBÈRES a bloqué une demande officielle de reprise d’ORPHÉE.'),
('039', 'POINT ZÉRO', 'Le dossier final confirme que le danger vient de la continuité humaine et politique autour d’ORPHÉE, pas d’un mécanisme technique isolé.', 'RÉSEAU TOUJOURS ACTIF', 'Des responsables ont continué à coordonner des actions autour d’ORPHÉE après sa fermeture.'),
('041', 'GIRI', 'La dette ancienne a été rappelée juste avant le meurtre et relie l’exécutant à un relais institutionnel.', 'GIRI', 'Le Kobun Kurokawa reçoit un rappel d’une ancienne faveur peu avant le meurtre. Un contact policier y est lié.'),
('042', 'MAINS SALES', 'La police a utilisé les clans comme intermédiaires pour obtenir ce qu’elle ne pouvait pas demander officiellement.', 'DEMANDES HORS PROCÉDURE', 'Un policier a demandé des actions aux clans sans passer par la procédure officielle.'),
('043', 'LA DETTE', 'La chaîne la plus cohérente relie une ancienne faveur policière au meurtre matériel puis à une orientation préparée de l’enquête.', 'CONTACTS AVANT LE MEURTRE', 'Des contacts policiers ont eu lieu avant le meurtre. Une version des faits était prête très vite après.'),
('044', 'LE CONSEIL', 'Les fragments convergent : l’Oyabun voulait sortir du système, le Kobun l’a tué sous une dette activée et un relais policier avait préparé la couverture et l’orientation de l’enquête.', 'APPEL AVANT LE MEURTRE', 'Avant le meurtre, un policier contacte le Kobun Kurokawa. Après, une version accusant Arakida est préparée.')
)
UPDATE public.igr_v4_events ev
 SET payload=jsonb_set(jsonb_set(ev.payload,'{text}',to_jsonb(x.new_text),true),'{title}',to_jsonb(x.new_title),true)
FROM public.igr_v4_rooms r JOIN edits x ON x.scenario_id=r.scenario_id
WHERE ev.room_code=r.code AND ev.event_type='trame'
 AND ev.payload->>'title'=x.old_title
 AND ev.payload->>'text'=x.old_text
RETURNING ev.id,ev.room_code,x.scenario_id,x.new_title;
